  ('t220', 220, 'نظام ادارة التسميح المالي', 'سيناريوهات نظام التسميح المالي', 'حركات الإيداعات للعملاء', 2, 'إضافة إيداع جديد', 'تسجيل سند قبض وإضافة مبلغ لحساب العميل.', '["اختيار العميل.","مراجعة الرصيد المتاح والمحجوز والمديونية.","إدخال المبلغ والعملة وطريقة الدفع ورقم المرجع."]'::jsonb, '["• تظهر البيانات المطلوبة جاهزة للحفظ"]'::jsonb, true),
