  ('t222', 222, 'نظام ادارة التسميح المالي', 'سيناريوهات نظام التسميح المالي', 'حركات الإيداعات للعملاء', 4, 'رفع وإدارة المرفق', 'إرفاق مستند الإيداع وإدارته.', '["رفع المرفق.","عرضه أو تحميله أو حذفه وفق الصلاحية."]'::jsonb, '["• يظهر المرفق مرتبطًا بسند القبض"]'::jsonb, true),
  ('t223', 223, 'نظام ادارة التسميح المالي', 'سيناريوهات نظام التسميح المالي', 'حركات الإيداعات للعملاء', 5, 'حفظ السند وتحديث الرصيد', 'اعتماد الإيداع وإضافته إلى حساب العميل.', '["اختيار «حفظ السند وإيداع بالحساب»."]'::jsonb, '["• يُنشأ رقم سند","• تزداد قيمة الرصيد المتاح بالعملة المختارة"]'::jsonb, true),
  ('t224', 224, 'نظام ادارة التسميح المالي', 'سيناريوهات نظام التسميح المالي', 'مراجعة وتسوية أذونات التوريد للعملاء', 1, 'البحث عن أذونات التوريد', 'البحث بالعميل وحالة السداد وفترة إصدار الإذن.', '["إدخال محددات البحث.","الضغط على بحث."]'::jsonb, '["• تظهر أذونات التوريد المطابقة وحالة كل إذن"]'::jsonb, true),
