  ('t226', 226, 'نظام ادارة التسميح المالي', 'سيناريوهات نظام التسميح المالي', 'مراجعة وتسوية أذونات التوريد للعملاء', 3, 'تحديد عدة أذونات', 'اختيار أذونات العميل المطلوب تسويتها.', '["تحديد إذن واحد أو أكثر."]'::jsonb, '["• يظهر عدد الأذونات المحددة وإجمالي المطلوب بكل عملة"]'::jsonb, true),
  ('t227', 227, 'نظام ادارة التسميح المالي', 'سيناريوهات نظام التسميح المالي', 'مراجعة وتسوية أذونات التوريد للعملاء', 4, 'إضافة إيداع من شاشة الأذونات', 'تسجيل إيداع للعميل أثناء مراجعة أذونات التوريد.', '["اختيار «إضافة حركة إيداع».","استكمال سند القبض وحفظه."]'::jsonb, '["• يُضاف المبلغ إلى حساب العميل وتُحدث بيانات الرصيد"]'::jsonb, true),
  ('t228', 228, 'نظام ادارة التسميح المالي', 'سيناريوهات نظام التسميح المالي', 'مراجعة وتسوية أذونات التوريد للعملاء', 5, 'تغطية الأذونات من رصيد كاف', 'تسوية الأذونات المحددة من الرصيد المتاح.', '["تحديد الأذونات.","اختيار «تغطية فورية من الرصيد»."]'::jsonb, '["• تُخصم القيم المطلوبة حسب العملة","• تتغير حالة الأذونات إلى «تم الإيداع»"]'::jsonb, true),
  ('t229', 229, 'نظام ادارة التسميح المالي', 'سيناريوهات نظام التسميح المالي', 'مراجعة وتسوية أذونات التوريد للعملاء', 6, 'منع التغطية عند عدم كفاية الرصيد', 'محاولة تسوية أذونات تتجاوز الرصيد المتاح.', '["تحديد الأذونات والضغط على التغطية."]'::jsonb, '["• لا تمت التسوية","• تظهر رسالة بعدم كفاية الرصيد المطلوب"]'::jsonb, true),
  ('t230', 230, 'نظام ادارة التسميح المالي', 'سيناريوهات نظام التسميح المالي', 'مراجعة وتسوية الفواتير', 1, 'البحث عن الفواتير المعلقة', 'البحث بفترة الاستحقاق والتوكيل الملاحي.', '["اختيار التوكيل وتحديد الفترة.","الضغط على بحث الفواتير المعلقة."]'::jsonb, '["• تظهر جميع الفواتير ورصيد العميل المتاح"]'::jsonb, true),
  ('t231', 231, 'نظام ادارة التسميح المالي', 'سيناريوهات نظام التسميح المالي', 'مراجعة وتسوية الفواتير', 2, 'تحديد الفواتير وحساب الإجمالي', 'اختيار الفواتير المطلوب سدادها.', '["اختيار التوكيل الملاحي.","تحديد فاتورة واحدة أو أكثر."]'::jsonb, '["• يظهر عدد الفواتير وإجمالي القيمة بالجنيه والدولار"]'::jsonb, true),
  ('t232', 232, 'نظام ادارة التسميح المالي', 'سيناريوهات نظام التسميح المالي', 'مراجعة وتسوية الفواتير', 3, 'تسوية الفواتير من رصيد كاف', 'سداد الفواتير المحددة من الرصيد الدائن المتاح.', '["تحديد الفواتير.","اختيار «خصم من الرصيد المتاح»."]'::jsonb, '["• تُخصم القيمة بالعملة الصحيحة","• تتغير حالة الفواتير إلى «مسددة»"]'::jsonb, true),
  ('t233', 233, 'نظام ادارة التسميح المالي', 'سيناريوهات نظام التسميح المالي', 'مراجعة وتسوية الفواتير', 4, 'منع التسوية عند عدم كفاية الرصيد', 'محاولة سداد فواتير تتجاوز الرصيد الدائن المتاح.', '["تحديد الفواتير والضغط على الخصم."]'::jsonb, '["• لا يتم الخصم","• تظهر رسالة بعدم كفاية الرصيد"]'::jsonb, true),
  ('t234', 234, 'نظام ادارة التسميح المالي', 'سيناريوهات نظام التسميح المالي', 'حسابي المالي', 1, 'عرض الموقف المالي', 'عرض ملخص حساب العميل بالجنيه والدولار.', '["فتح شاشة حسابي المالي."]'::jsonb, '["• يظهر الرصيد المتاح والمحجوز والمديونية السابقة بكل عملة"]'::jsonb, true),
  ('t235', 235, 'نظام ادارة التسميح المالي', 'سيناريوهات نظام التسميح المالي', 'حسابي المالي', 2, 'البحث في الفواتير', 'عرض فواتير العميل باستخدام محددات البحث.', '["فتح تبويب الفواتير.","اختيار النوع والحالة وفترة الاستحقاق ثم البحث."]'::jsonb, '["• تظهر الفواتير المطابقة وبيانات السداد"]'::jsonb, true),
  ('t236', 236, 'نظام ادارة التسميح المالي', 'سيناريوهات نظام التسميح المالي', 'حسابي المالي', 3, 'البحث في أذونات التوريد', 'عرض أذونات التوريد الخاصة بالعميل.', '["فتح تبويب أذونات التوريد.","إدخال رقم الإذن أو نوع الخدمة أو الحالة أو الفترة ثم البحث."]'::jsonb, '["• تظهر الأذونات المطابقة وحالة كل إذن"]'::jsonb, true),
  ('t237', 237, 'نظام ادارة التسميح المالي', 'سيناريوهات نظام التسميح المالي', 'حسابي المالي', 4, 'البحث في الإيداعات', 'عرض حركات الإيداع الخاصة بالعميل.', '["فتح تبويب الإيداعات.","اختيار تاريخ الإيداع ثم البحث."]'::jsonb, '["• تظهر سندات القبض وبيانات الإيداع"]'::jsonb, true),
  ('t238', 238, 'نظام ادارة التسميح المالي', 'سيناريوهات نظام التسميح المالي', 'حسابي المالي', 5, 'مسح البحث وتحميل النتائج', 'إدارة نتائج البحث داخل تبويبات الحساب المالي.', '["مسح محددات البحث أو اختيار تحميل النتائج."]'::jsonb, '["• تعود القائمة للوضع الافتراضي أو يتم تحميل النتائج","• تظهر رسالة واضحة عند عدم وجود بيانات"]'::jsonb, true),
  ('t239', 239, 'نظام إدارة خدمة العملاء', 'سيناريوهات إدارة الشكاوى والمقترحات', '', 1, 'إنشاء شكوى أو مقترح وحفظه كمسودة', 'إنشاء شكوى أو مقترح جديد وإدخال البيانات المطلوبة ثم حفظه كمسودة دون إرساله لإتاحة استكمال البيانات أو تعديلها وإرساله لاحقا.', '["تسجيل الدخول والضغط على الصورة الشخصية.","الضغط على خدمة العملاء.","الضغط علي زر إضافة شكوي / مقترح.","تحديد النوع وإدخال العنوان والتفاصيل وإضافة المرفقات عند الحاجة.","الضغط على حفظ.","فتح الطلب لاحقًا لاستكماله أو تعديله."]'::jsonb, '["• تصبح حالة الطلب لم يقدم","• يتم حفظ البيانات دون إرسال الطلب","• يمكن للمستخدم تعديل الطلب وإرساله لاحقًا"]'::jsonb, true),
  ('t240', 240, 'نظام إدارة خدمة العملاء', 'سيناريوهات إدارة الشكاوى والمقترحات', '', 2, 'تقديم شكوى أو مقترح وإرساله', 'تقديم شكوى أو مقترح مكتمل البيانات وإرساله إلى خدمة العملاء لبدء المراجعة والمتابعة مع منع العميل من تعديل الطلب بعد الإرسال.', '["فتح شاشة تقديم شكوى / مقترح.","تحديد النوع وإدخال العنوان والتفاصيل.","إضافة المرفقات عند الحاجة.","الضغط على إرسال."]'::jsonb, '["• يتم إرسال الطلب إلى خدمة العملاء","• تصبح حالة الطلب تحت المراجعة","• يتم إنشاء رقم مرجعي فريد للطلب","• لا يمكن للعميل تعديل بيانات الطلب بعد الإرسال","• يبدأ مؤقت تصعيد خدمة العملاء"]'::jsonb, true),
  ('t241', 241, 'نظام إدارة خدمة العملاء', 'سيناريوهات إدارة الشكاوى والمقترحات', '', 3, 'عدم استيفاء بيانات الشكوى أو المقترح', 'محاولة حفظ أو إرسال شكوى أو مقترح دون استكمال البيانات الإلزامية للتحقق من منع العملية وتوضيح البيانات المطلوب استكمالها.', '["فتح شاشة تقديم شكوى / مقترح.","ترك النوع أو العنوان أو التفاصيل دون إدخال.","الضغط على حفظ أو إرسال."]'::jsonb, '["• لا يتم حفظ الطلب أو إرساله","• يتم تحديد الحقول الإلزامية غير المستوفاة باللون الأحمر","• تظهر رسائل توضح البيانات المطلوب استكمالها"]'::jsonb, true),
  ('t242', 242, 'نظام إدارة خدمة العملاء', 'سيناريوهات إدارة الشكاوى والمقترحات', '', 4, 'مراجعة خدمة العملاء للشكوى أو المقترح', 'استلام خدمة العملاء لشكوى أو مقترح مقدم من العميل ومراجعة بياناته ومرفقاته والتواصل مع العميل قبل اتخاذ الإجراء المناسب.', '["يدخل موظف خدمة العملاء إلى لوحة قيادة الشكاوى والمقترحات.","يختار الطلب ويضغط على تفاصيل.","يراجع البيانات والوصف التفصيلي والمرفقات.","يفتح تبويب المتابعة مع العميل.","يرسل رسالة نصية للعميل عند الحاجة."]'::jsonb, '["• تظهر جميع بيانات الطلب ومرفقاته لموظف خدمة العملاء","• يتم حفظ الرسائل ضمن سجل المحادثة"]'::jsonb, true),
  ('t243', 243, 'نظام إدارة خدمة العملاء', 'سيناريوهات إدارة الشكاوى والمقترحات', '', 5, 'توجيه الشكوى أو المقترح إلى الإدارة المختصة', 'توجيه خدمة العملاء للشكوى أو المقترح إلى الإدارة المختصة بعد مراجعة الحالة، مع تحديد درجة الأولوية وتسجيل تعليق يوضح سبب التوجيه.', '["يفتح موظف خدمة العملاء تفاصيل الطلب.","يضغط على توجيه إلى الإدارات.","يحدد الإدارة المختصة ودرجة الأولوية.","يدخل تعليق خدمة العملاء.","يضغط على حفظ."]'::jsonb, '["• يتم توجيه الحالة إلى الإدارة المحددة","• تصبح حالة الطلب المتابعة مع الإدارة","• يتوقف مؤقت تصعيد خدمة العملاء","• يبدأ مؤقت تصعيد مستقل للإدارة من لحظة التوجيه"]'::jsonb, true),
  ('t244', 244, 'نظام إدارة خدمة العملاء', 'سيناريوهات إدارة الشكاوى والمقترحات', '', 6, 'متابعة خدمة العملاء مع الإدارة المختصة', 'متابعة خدمة العملاء للشكوى أو المقترح بعد توجيهه إلى الإدارة المختصة من خلال الاطلاع على تفاصيل التوجيه وتبادل الرسائل النصية معها حتى استكمال معالجة الحالة.', '["يفتح موظف خدمة العملاء تفاصيل الطلب.","ينتقال إلى تبويب المتابعة مع الإدارات.","يختار الإدارة المطلوب متابعتها.","يراجع تفاصيل التوجيه والمحادثة الخاصة بها.","يرسل رسالة نصية إلى الإدارة.","يستقبل رد الإدارة ويستكمل المتابعة."]'::jsonb, '["• يتم حفظ الرسائل داخل المحادثة الخاصة بالإدارة المحددة","• تظهر الرسائل الجديدة داخل نفس المحادثة","• تظل المحادثات الخاصة بالإدارات المختلفة مستقلة","• يستمر مؤقت تصعيد الإدارة أثناء تبادل الرسائل"]'::jsonb, true),
  ('t245', 245, 'نظام إدارة خدمة العملاء', 'سيناريوهات إدارة الشكاوى والمقترحات', '', 7, 'استلام الإدارة للشكوى أو المقترح ومراجعة التفاصيل', 'استلام الإدارة المختصة للشكوى أو المقترح الموجه إليها من خدمة العملاء والاطلاع على جميع بيانات الحالة وسياق التوجيه والمرفقات والسجلات السابقة قبل إعداد الرد.', '["تقوم خدمة العملاء بتوجيه الحالة إلى الإدارة المختصة.","يستلم موظفو الإدارة أصحاب الصلاحية إشعارًا بالحالة.","يفتح موظف الإدارة تفاصيل الشكوى أو المقترح.","يراجع البيانات والوصف التفصيلي والمرفقات.","يطلع على تعليق التوجيه ودرجة الأهمية.","يراجع سجل العميل وسجل النشاطات عند الحاجة."]'::jsonb, '["• تظهر الحالة للإدارة الموجه إليها فقط","• يتم عرض مؤقت تصعيد الإدارة أعلى شاشة التفاصيل","• تظهر بيانات التوجيه والمرفقات والسجلات للقراءة فقط","• لا تستطيع الإدارة تغيير حالة الطلب أو غلقه أو البت النهائي فيه"]'::jsonb, true),
  ('t246', 246, 'نظام إدارة خدمة العملاء', 'سيناريوهات إدارة الشكاوى والمقترحات', '', 8, 'إرسال رد الإدارة إلى خدمة العملاء', 'إرسال موظف الإدارة المختصة ردا نصيًا إلى خدمة العملاء بعد مراجعة الشكوى أو المقترح مع حفظ الرد وإشعار خدمة العملاء لاستكمال المتابعة.', '["يفتح موظف الإدارة تفاصيل الحالة.","ينتقل إلى تبويب المتابعة مع خدمة العملاء.","يراجع الرسائل الموجودة في المحادثة.","يكتب الرد النصي ويضغط على إرسال رسالة.","يستقبل موظف خدمة العملاء إشعارًا بالرد الجديد."]'::jsonb, '["• يتم حفظ الرد باسم المرسل وتاريخ ووقت الإرسال","• يظهر الرد في المحادثة المشتركة بين الإدارة وخدمة العملاء","• لا يمكن تعديل الرسالة أو حذفها بعد الإرسال","• لا يتوقف مؤقت التصعيد بمجرد إرسال الرد","• تظل حالة الطلب المتابعة مع الإدارة"]'::jsonb, true),
  ('t247', 247, 'نظام إدارة خدمة العملاء', 'سيناريوهات إدارة الشكاوى والمقترحات', '', 9, 'تصعيد الشكوى أو المقترح على خدمة العملاء', 'تصعيد الشكوى أو المقترح تلقائيًا إلى المسؤول الأعلى عند انتهاء المدة المحددة لخدمة العملاء دون توجيه الحالة إلى إدارة.', '["يرسل العميل الشكوى أو المقترح.","يبدأ النظام مؤقت تصعيد خدمة العملاء.","تنتهي المدة المحددة دون توجيه الحالة إلى إدارة.","ينفذ النظام التصعيد التلقائي.","يرسل إشعارًا إلى المسؤول الأعلى المحدد في الإعدادات."]'::jsonb, '["• يتم تصعيد الحالة مرة واحدة إلى المسؤول الأعلى الخاص بخدمة العملاء","• يتوقف مؤقت التصعيد لهذه المرحلة","• تظل الحالة مسندة إلى موظف خدمة العملاء الأصلي","• يستطيع المسؤول الأعلى الاطلاع على الحالة ومتابعتها"]'::jsonb, true),
  ('t248', 248, 'نظام إدارة خدمة العملاء', 'سيناريوهات إدارة الشكاوى والمقترحات', '', 10, 'منع تصعيد خدمة العملاء عند التوجيه قبل انتهاء المدة', 'توجيه خدمة العملاء للشكوى أو المقترح إلى الإدارة المختصة قبل انتهاء مهلة التصعيد لمنع تصعيد مرحلة خدمة العملاء والانتقال إلى مؤقت الإدارة.', '["يرسل العميل الشكوى أو المقترح.","يبدأ مؤقت تصعيد خدمة العملاء.","يوجه موظف خدمة العملاء الحالة إلى إدارة قبل انتهاء المدة.","يبدأ النظام مؤقت الإدارة الجديدة."]'::jsonb, '["• يتوقف مؤقت خدمة العملاء دون تنفيذ تصعيد","• يبدأ مؤقت الإدارة من الصفر","• تنتقل الحالة إلى المتابعة مع الإدارة"]'::jsonb, true),
  ('t249', 249, 'نظام إدارة خدمة العملاء', 'سيناريوهات إدارة الشكاوى والمقترحات', '', 11, 'تصعيد الشكوى أو المقترح على الإدارة', 'تصعيد الشكوى أو المقترح تلقائيًا إلى المسؤول الأعلى عند انتهاء مدة الإدارة دون غلق الحالة أو تنفيذ إجراء تم البت فيها حتى لو كانت الإدارة قد أرسلت ردا لخدمة العملاء.', '["توجه خدمة العملاء الحالة إلى الإدارة المختصة.","يبدأ مؤقت تصعيد الإدارة.","تتابع الإدارة الحالة أو ترسل ردًا دون غلقها أو البت النهائي فيها.","تنتهي مدة التصعيد المحددة.","ينفذ النظام التصعيد ويرسل إشعارًا للمسؤول الأعلى."]'::jsonb, '["• يتم تصعيد الحالة مرة واحدة للمسؤول الأعلى المحدد للإدارة","• ينتهي مؤقت التصعيد لهذه المرحلة","• تظل الحالة مسندة إلى الإدارة الأصلية","• تستمر الإدارة في المتابعة بجانب المسؤول الأعلى"]'::jsonb, true),
  ('t250', 250, 'نظام إدارة خدمة العملاء', 'سيناريوهات إدارة الشكاوى والمقترحات', '', 12, 'منع تصعيد الإدارة عند إنهاء الحالة قبل انتهاء المدة', 'إنهاء الشكوى أو المقترح بواسطة خدمة العملاء قبل انتهاء مدة تصعيد الإدارة سواء من خلال الغلق أو تنفيذ إجراء تم البت فيها.', '["يتم توجيه الحالة إلى الإدارة ويبدأ مؤقت التصعيد.","تتابع خدمة العملاء الحالة مع الإدارة.","تنفذ خدمة العملاء إجراء الغلق أو تم البت فيها قبل انتهاء المدة.","يوقف النظام مؤقت الإدارة."]'::jsonb, '["• يتوقف مؤقت تصعيد الإدارة","• لا يتم تنفيذ تصعيد لهذه المرحلة","• تتحول محادثات المتابعة إلى وضع القراءة فقط"]'::jsonb, true),
  ('t251', 251, 'نظام إدارة خدمة العملاء', 'سيناريوهات إدارة الشكاوى والمقترحات', '', 13, 'متابعة المسؤول الأعلى لتصعيد خدمة العملاء', 'متابعة المسؤول الأعلى للشكوى أو المقترح بعد تصعيده على خدمة العملاء من خلال محادثة مستقلة مع موظف خدمة العملاء دون تغيير إسناد الحالة أو اتخاذ إجراءات الغلق.', '["ينفذ النظام التصعيد التلقائي على خدمة العملاء.","يستلم المسؤول الأعلى إشعارًا بالحالة المتصعدة.","يفتح تفاصيل الشكوى أو المقترح.","يختار خدمة العملاء من تبويب المتابعة مع الموظفين.","فتح المحادثة المستقلة ويرسل رسالة نصية.","يستكمل المتابعة مع موظف خدمة العملاء."]'::jsonb, '["• يظهر تنبيه تم التصعيد إلى المدير المسؤول بدلًا من مؤقت تصعيد جديد","• يتم إنشاء محادثة مستقلة بين المسؤول الأعلى وخدمة العملاء فقط","• تظل الحالة مسندة إلى موظف خدمة العملاء الأصلي","• لا يستطيع المسؤول الأعلى تغيير الحالة أو غلقها أو البت النهائي فيها"]'::jsonb, true),
  ('t252', 252, 'نظام إدارة خدمة العملاء', 'سيناريوهات إدارة الشكاوى والمقترحات', '', 14, 'متابعة المسؤول الأعلى لتصعيد الإدارة', 'متابعة المسؤول الأعلى للشكوى أو المقترح بعد تصعيده على الإدارة المختصة من خلال محادثة مستقلة معها مع استمرار الإدارة في معالجة الحالة دون نقل الإسناد.', '["ينفذ النظام التصعيد التلقائي على الإدارة.","يستلم المسؤول الأعلى إشعارًا بالحالة.","يفتح تفاصيل الشكوى أو المقترح.","يختار الإدارة المتصعد عليها من تبويب المتابعة مع الموظفين.","يرسل رسالة نصية داخل المحادثة المستقلة.","تستمر الإدارة في المتابعة والرد."]'::jsonb, '["• تظهر محادثة مستقلة بين المسؤول الأعلى والإدارة المتصعد عليها","• تظل الحالة مسندة إلى الإدارة الأصلية"]'::jsonb, true),
  ('t253', 253, 'نظام إدارة خدمة العملاء', 'سيناريوهات إدارة الشكاوى والمقترحات', '', 15, 'غلق الشكوى أو المقترح وإنهاء المتابعة', 'إنهاء متابعة الشكوى أو المقترح بعد قيام خدمة العملاء بغلق الحالة أو تنفيذ إجراء تم البت فيها مع الاحتفاظ بجميع المحادثات والسجلات السابقة للرجوع إليها.', '["تستمر خدمة العملاء والإدارة في متابعة الحالة.","يقوم موظف خدمة العملاء بتنفيذ إجراء الغلق أو تم البت فيها.","يوقف النظام مؤقت التصعيد إذا كان لا يزال قائمًا."]'::jsonb, '["• تتوقف إمكانية إرسال رسائل جديدة","• تصبح محادثات الإدارة والمسؤول الأعلى للقراءة فقط","• تظل الرسائل والمرفقات وسجل النشاطات محفوظة","• لا يمكن تعديل الرسائل السابقة أو حذفها"]'::jsonb, true),
  ('t254', 254, 'نظام إدارة خدمة العملاء', 'سيناريوهات إدارة الاستبيانات', '', 1, 'إنشاء الاستبيان وحفظه كمسودة', 'إنشاء استبيان جديد وإضافة بياناته وأسئلته ثم حفظه كمسودة لاستكماله أو تعديله لاحقا قبل الاعتماد.', '["الدخول إلى لوحة قيادة الاستبيانات.","الضغط على إنشاء استبيان جديد.","إدخال بيانات الاستبيان وإضافة الأسئلة وإعداداتها.","الضغط على حفظ مسودة."]'::jsonb, '["• تصبح حالة الاستبيان مسودة"]'::jsonb, true),
  ('t255', 255, 'نظام إدارة خدمة العملاء', 'سيناريوهات إدارة الاستبيانات', '', 2, 'اعتماد الاستبيان', 'استكمال بيانات الاستبيان وأسئلته والتأكد من استيفاء المتطلبات الإلزامية ثم اعتماده ليصبح جاهزا للإرسال.', '["فتح الاستبيان المحفوظ كمسودة.","الضغط على اعتماد نهائي للنموذج.","يتحقق النظام من البيانات ويعتمد الاستبيان."]'::jsonb, '["• يتم اعتماد الاستبيان بنجاح","• تصبح حالة الاستبيان معتمد","• يصبح الاستبيان جاهزا للإرسال"]'::jsonb, true),
  ('t256', 256, 'نظام إدارة خدمة العملاء', 'سيناريوهات إدارة الاستبيانات', '', 3, 'تعديل الاستبيان قبل الإرسال', 'تعديل بيانات استبيان بحالة مسودة أو معتمد، بشرط عدم إرساله للمستفيدين وعدم تسجيل إجابات عليه مع الاحتفاظ بنفس رقم الاستبيان.', '["اختيار الاستبيان من لوحة القيادة والضغط على تعديل.","تعديل بيانات الاستبيان أو الأسئلة أو الخيارات.","الضغط على حفظ وتأكيد العملية."]'::jsonb, '["• يتم حفظ التعديلات بنجاح","• يحتفظ الاستبيان بنفس رقمه","• تظهر البيانات المحدثة في لوحة القيادة"]'::jsonb, true),
  ('t257', 257, 'نظام إدارة خدمة العملاء', 'سيناريوهات إدارة الاستبيانات', '', 4, 'منع تعديل الاستبيان بعد الإرسال', 'محاولة تعديل استبيان سبق إرساله للمستفيدين للتحقق من منع التعديل والحفاظ على بياناته كما هي.', '["الدخول إلى لوحة قيادة الاستبيانات.","اختيار استبيان تم إرساله للمستفيدين.","محاولة الدخول إلى إجراء التعديل."]'::jsonb, '["• لا يسمح النظام بالدخول إلى وضع التعديل","• تظل بيانات الاستبيان دون تغيير"]'::jsonb, true),
  ('t258', 258, 'نظام إدارة خدمة العملاء', 'سيناريوهات إدارة الاستبيانات', '', 5, 'حذف الاستبيان قبل الإرسال', 'حذف استبيان لم يعد مطلوبا، بشرط عدم إرساله للمستفيدين وعدم وجود إجابات مرتبطة به.', '["اختيار استبيان بحالة مسودة أو معتمد لم يتم إرساله.","الضغط على حذف من عرض البطاقات أو الجدول.","تأكيد عملية الحذف."]'::jsonb, '["• يتم حذف الاستبيان نهائيا","• يختفي الاستبيان من لوحة القيادة","• يتم تحديث الإحصائيات المرتبطة بالاستبيانات"]'::jsonb, true),
  ('t259', 259, 'نظام إدارة خدمة العملاء', 'سيناريوهات إدارة الاستبيانات', '', 6, 'منع حذف الاستبيان بعد الإرسال', 'محاولة حذف استبيان تم إرساله أو يحتوي على إجابات، للتحقق من منع الحذف والحفاظ على البيانات المسجلة.', '["اختيار الاستبيان المطلوب حذفه.","محاولة تنفيذ إجراء الحذف.","يتحقق النظام من حالة الاستبيان ووجود إجابات مرتبطة به."]'::jsonb, '["• لا يتم حذف الاستبيان","• تظهر رسالة توضح سبب عدم إمكانية الحذف","• تظل بيانات الاستبيان محفوظة دون تغيير"]'::jsonb, true),
  ('t260', 260, 'نظام إدارة خدمة العملاء', 'سيناريوهات إدارة الاستبيانات', '', 7, 'نسخ استبيان موجود', 'إنشاء نسخة جديدة ومستقلة من استبيان موجود مع الاحتفاظ ببياناته وأسئلته دون نقل الإجابات أو النتائج أو بيانات الإرسال.', '["اختيار الاستبيان المطلوب نسخ من لوحة القيادة.","الضغط على نسخ الاستبيان.","تأكيد عملية النسخ.","فتح النسخة الجديدة لاستكمالها أو تعديلها."]'::jsonb, '["• يتم إنشاء استبيان جديد برقم مستقل وحالة مسودة","• يتم نسخ البيانات والأسئلة والخيارات بنفس الترتيب","• لا يتم نسخ الإجابات أو النتائج أو بيانات الإرسال","• تفتح النسخة الجديدة مباشرة في شاشة التعديل دون التأثير على الاستبيان الأصلي"]'::jsonb, true),
  ('t261', 261, 'نظام إدارة خدمة العملاء', 'سيناريوهات إدارة الاستبيانات', '', 8, 'عرض وطباعة الاستبيان', 'عرض جميع بيانات الاستبيان وأسئلته وبيانات إرساله للقراءة فقط، مع إمكانية طباعة نفس المحتوى دون إظهار إجابات المستفيدين.', '["اختيار الاستبيان من لوحة القيادة.","الضغط على عرض وطباعة الاستبيان.","مراجعة بيانات الاستبيان وأسئلته وبيانات الإرسال.","الضغط على طباعة."]'::jsonb, '["• يتم عرض الاستبيان بكامل تفاصيله للقراءة فقط","• تظهر الأدوار المستهدفة وتاريخ الإرسال والإغلاق عند وجود بيانات إرسال","• تتم طباعة نفس البيانات المعروضة دون إجابات المستفيدين أو نتائجها"]'::jsonb, true),
  ('t262', 262, 'نظام إدارة خدمة العملاء', 'سيناريوهات إدارة الاستبيانات', '', 9, 'استلام الاستبيان وإرسال الإجابة', 'استلام المستخدم المستهدف لاستبيان مفتوح والإجابة على أسئلته الإلزامية ثم تأكيد إرسال الإجابة وحفظها نهائيا.', '["يستلم المستخدم إشعارا بالاستبيان ويفتحه.","يجيب عن الأسئلة الإلزامية، ويمكنه ترك الأسئلة الاختيارية.","يضغط على إرسال الإجابة.","يؤكد عملية الإرسال."]'::jsonb, '["• يتم حفظ الإجابات وتظهر رسالة نجاح","• تصبح حالة الاستبيان بالنسبة للمستخدم مكتمل","• يختفي الاستبيان من قائمة المستخدم","• لا يمكن للمستخدم إعادة فتح الاستبيان أو تعديل إجابته"]'::jsonb, true),
  ('t263', 263, 'نظام إدارة خدمة العملاء', 'سيناريوهات إدارة الاستبيانات', '', 10, 'عدم استكمال الأسئلة الإلزامية', 'محاولة إرسال إجابة على استبيان دون استكمال جميع الأسئلة الإلزامية، للتحقق من عدم السماح بالإرسال حتى استيفائها.', '["يفتح المستخدم الاستبيان.","يجيب عن بعض الأسئلة ويترك سؤالًا إلزاميًا دون إجابة.","يحاول إرسال الإجابة."]'::jsonb, '["• لا يتم إرسال أي إجابة","• يصبح الإرسال متاحا بعد استكمال جميع الأسئلة الإلزامية"]'::jsonb, true),
  ('t264', 264, 'نظام إدارة خدمة العملاء', 'سيناريوهات إدارة الاستبيانات', '', 11, 'إغلاق الاستبيان تلقائيا', 'انتهاء الفترة المحددة للإجابة على الاستبيان ليقوم النظام بإغلاقه تلقائيا ومنع استقبال إجابات جديدة.', '["يكون الاستبيان مرسلا ومتاحا للمستخدمين المستهدفين.","يحل تاريخ الإغلاق المحدد للاستبيان.","يغلق النظام الاستبيان تلقائيا."]'::jsonb, '["• تصبح حالة الاستبيان مغلق حتى في حالة عدم وجود إجابات","• لا يمكن للمستخدمين إرسال إجابات جديدة","• يختفي الاستبيان من قوائم الاستبيانات المتاحة للمستخدمين"]'::jsonb, true),
  ('t265', 265, 'نظام إدارة خدمة العملاء', 'سيناريوهات إدارة الاستبيانات', '', 12, 'عرض إجابات الاستبيان المغلق', 'عرض إجابات ونتائج استبيان مغلق لمراجعتها مع إمكانية التنقل بين الإجابات وعرض المرفقات دون تعديل البيانات.', '["اختيار استبيان بحالة مغلق من لوحة القيادة.","الضغط على عرض إجابات الاستبيان.","مراجعة الإجابات والنتائج والإحصائيات.","التنقل بين صفحات الإجابات وعرض المرفقات أو تحميلها عند الحاجة."]'::jsonb, '["• تظهر جميع الإجابات والنتائج المسجلة","• يمكن التنقل بين الإجابات وعرض المرفقات وتحميلها","• تكون جميع البيانات للقراءة فقط دون إمكانية تعديلها"]'::jsonb, true),
  ('t266', 266, 'نظام إدارة خدمة العملاء', 'سيناريوهات إدارة الاستبيانات', '', 13, 'عرض استبيان مغلق دون إجابات', 'عرض نتائج استبيان انتهت فترة الإجابة عليه دون مشاركة أي مستخدم مع إظهار بياناته وتوضيح أن لا يوجد إجابات.', '["اختيار استبيان مغلق لا يحتوي على إجابات.","الضغط على عرض إجابات الاستبيان.","فتح شاشة النتائج ومراجعة البيانات."]'::jsonb, '["• يتم عرض بيانات الاستبيان","• لا يتم عرض أي بيانات لإجابات غير موجودة","153 / 153\n23H Dr","Yehia El Mashad st",", Smouha, Alexandria 21615, Egypt | www","isfpegypt","com | 23 هـ شارع د","يحيى المشد، عمارة الأكاديمية، سموحة، الإسكندرية 21615، ج","م","ع\nTel: (+203) 429-3846 / 429-4632 Fax: (+203) 429-4357 | info@isfpegypt","com | ت: 4632-429 / 3846-429 (203+) ف: 4357-429 (203+)"]'::jsonb, true)
on conflict (id) do nothing;
