  ('t84', 84, 'نظام إدارة البوابات', 'سناريوهات إدارة البوابات', '', 4, '.6: تسجيل طلب حجز شاحنات الحاويات ( حجز صادر )', 'تسجيل طلب حجز شاحنات الحاويات عن طريق شركة النقل', '["فتح طلبات الحجز من اللوحة التفاعلية لشركة النقل اختيار الميناء المقدم به الحجز ونقطة الحجز يتم اختيار نوع الحجز حجز صادر حاويات يتم إضافة الحاويات عن طريق البحث برقم الحاوية في حالة وجود الحاوية سيتم عرض الايزو الخاص بها في حالة انها حاوية جدية يتم تسجيل الايزو الخاص بها يجب وجود إقرار جمركي صادر لربط الحاويات به ويتم اختياره تسجيل الرقم الصحيح للإقرار في الخطوة التالية يتم تحديد الشاحنة والحفظ الخطوة التالية يتم إضافة المرفقات الإلزامية والغير الزامية ان وجد يمكن حفظ الطلب فقط بدون الارسال ويمكن التعديل عليه لاحقا"]'::jsonb, '["• انشاء طلب حجز لم يقدم في حالة عدم الارسال • انشاء طلب حجز تحت المراجعة في حالة الارسال"]'::jsonb, true),
  ('t85', 85, 'نظام إدارة البوابات', 'سناريوهات إدارة البوابات', '', 4, '.7: تسجيل طلب حجز شاحنات الحاويات ( تعتيق حاوية فارغ )', 'تسجيل طلب حجز شاحنات الحاويات عن طريق شركة النقل', '["فتح طلبات الحجز من اللوحة التفاعلية لشركة النقل اختيار الميناء المقدم به الحجز ونقطة الحجز يتم اختيار نوع الحجز تعتيق حاوية فارغ يجب ان تكون الحاوية فارغة يتم إضافة الحاويات عن طريق البحث برقم الحاوية في حالة وجود الحاوية سيتم عرض الايزو الخاص بها في حالة انها حاوية جدية يتم تسجيل الايزو الخاص بها في الخطوة التالية يتم تحديد الشاحنة والحفظ الخطوة التالية يتم إضافة المرفقات الإلزامية والغير الزامية ان وجد يمكن حفظ الطلب فقط بدون الارسال ويمكن التعديل عليه لاحقا"]'::jsonb, '["• انشاء طلب حجز لم يقدم في حالة عدم الارسال • انشاء طلب حجز تحت المراجعة في حالة الارسال"]'::jsonb, true),
  ('t86', 86, 'نظام إدارة البوابات', 'سناريوهات إدارة البوابات', '', 4, '.8: تسجيل طلب حجز شاحنات الحاويات ( استلام حاوية فارغ )', 'تسجيل طلب حجز شاحنات الحاويات عن طريق شركة النقل', '["فتح طلبات الحجز من اللوحة التفاعلية لشركة النقل اختيار الميناء المقدم به الحجز ونقطة الحجز يتم اختيار نوع الحجز استلام حاوية فارغ يجب ان تكون الحاوية فارغة يجب ان تكون داخل الميناء يتم إضافة الحاويات عن طريق البحث برقم الحاوية في حالة وجود الحاوية سيتم عرض الايزو الخاص بها في حالة انها حاوية جدية يتم تسجيل الايزو الخاص بها في الخطوة التالية يتم تحديد الشاحنة والحفظ الخطوة التالية يتم إضافة المرفقات الإلزامية والغير الزامية ان وجد يمكن حفظ الطلب فقط بدون الارسال ويمكن التعديل عليه لاحقا"]'::jsonb, '["• انشاء طلب حجز لم يقدم في حالة عدم الارسال • انشاء طلب حجز تحت المراجعة في حالة الارسال"]'::jsonb, true),
  ('t87', 87, 'نظام إدارة البوابات', 'سناريوهات إدارة البوابات', '', 4, '.9: تسجيل طلب حجز شاحنات الحاويات ( ارتجاع صادر)', 'تسجيل طلب حجز شاحنات الحاويات عن طريق شركة النقل', '["فتح طلبات الحجز من اللوحة التفاعلية لشركة النقل اختيار الميناء المقدم به الحجز ونقطة الحجز يتم اختيار نوع الحجز ارتجاع الصادر يجب ان تكون الحاوية مرتجع صادر تسجيل الرقم الصحيح للإقرار يتم الضغط على عرض الحاويات بعد عرض البضائع يتم اختيار البضائع المطلوب حجزها للشاحنة في الخطوة التالية يتم تحديد الشاحنة والحفظ الخطوة التالية يتم إضافة المرفقات الإلزامية والغير الزامية ان وجد يمكن حفظ الطلب فقط بدون الارسال ويمكن التعديل عليه لاحقا يمكن ارسال الطلب بعد الحفظ مباشرة او اغلاق الطلب ثم الارسال لاحقا"]'::jsonb, '["• انشاء طلب حجز لم يقدم في حالة عدم الارسال • انشاء طلب حجز تحت المراجعة في حالة الارسال"]'::jsonb, true),
  ('t88', 88, 'نظام إدارة البوابات', 'سناريوهات إدارة البوابات', '', 4, '.10: تسجيل طلب حجز شاحنات الحاويات ( استلام بدون حاوية )', 'تسجيل طلب حجز شاحنات الحاويات عن طريق شركة النقل', '["فتح طلبات الحجز من اللوحة التفاعلية لشركة النقل اختيار الميناء المقدم به الحجز ونقطة الحجز يتم اختيار نوع الحجز استلام بدون حاوية في الخطوة التالية يتم تحديد الشاحنة والحفظ الخطوة التالية يتم إضافة المرفقات الإلزامية والغير الزامية ان وجد يمكن حفظ الطلب فقط بدون الارسال ويمكن التعديل عليه لاحقا يمكن ارسال الطلب بعد الحفظ مباشرة او اغلاق الطلب ثم الارسال لاحقا"]'::jsonb, '["انشاء طلب حجز لم يقدم في حالة عدم الارسال انشاء طلب حجز تحت المراجعة في حالة الارسال"]'::jsonb, true),
  ('t89', 89, 'نظام إدارة البوابات', 'سناريوهات إدارة البوابات', '', 4, '.11: تسجيل طلب حجز شاحنات الخدمة', 'تسجيل طلب حجز شاحنات الخدمة عن طريق شركة النقل', '["فتح طلبات الحجز من اللوحة التفاعلية لشركة النقل اختيار الميناء المقدم به الحجز ونقطة الحجز يتم اختيار نوع الحجز تراخيص بالوحدة المرورية-مخلفات سفن-تموين مواد بترولية-مخلفات ذات قيمة مادية-كشف صادر - بدون شحن-خدمات نقل داخلي-القوات البحرية-حكومة-جيش-وزارة الدفاع-الترسانة-خدمات بدون وزن-قطاع عام-خدمات تموين سفن-خدمات هيئة ميناء-رصف طرق-صيانة-خدمات بوزن يجب ان تكون الخدمة مسجلة بشاشة البيانات الاساسية يتم تحديد من تاريخ ووقت الحجز الى تاريخ ووقت الحجز في الخطوة التالية يتم تحديد الشاحنة والحفظ الخطوة التالية يتم إضافة المرفقات الإلزامية والغير الزامية ان وجد يمكن حفظ الطلب فقط بدون الارسال ويمكن التعديل عليه لاحقا يمكن ارسال الطلب بعد الحفظ مباشرة او اغلاق الطلب ثم الارسال لاحقا"]'::jsonb, '["انشاء طلب حجز لم يقدم في حالة عدم الارسال انشاء طلب حجز تحت المراجعة في حالة الارسال"]'::jsonb, true),
  ('t90', 90, 'نظام إدارة البوابات', 'سناريوهات إدارة البوابات', '', 5, 'مراجعة طلب الحجز', 'مراجعة الموظف لطلب الحجز المقدم من شركة النقل', '["فتح طلبات الشاحنات من اللوحة التفاعلية لموظف البوابات تظهر الطلبات تحت المراجعة يتم اختيار الطلب المطلوب مراجعته الاطلاع على تفاصيل الطلب ومرفقاته اتخاذ القرار بالقبول او الرفض في حالة الرفض يتم تسجيل سبب الرفض ويقوم موظف شركة النقل بتعديل الطلب وارساله مرة أخرى للمراجعة"]'::jsonb, '["• في حالة الرفض تتحول حالة الطلب لمرفوض • في حالة القبول تتحول حالة الطلب لمقبول"]'::jsonb, true),
  ('t91', 91, 'نظام إدارة البوابات', 'سناريوهات إدارة البوابات', '', 6, 'دخول الشاحنات', 'تسجيل دخول شاحنة الى ميناء معين', '["فتح شاشة دخول الشاحنات اختيار البوابة والحارة المراد دخول الشاحنة منهم تحديد الشاحنة عن طريق البحث بالرقم الخاص بها الضغط على ايقونة البحث في حالة عدم وجود حجز فعال للشاحنة تظهر رسالة تفيد بذلك في حالة وجود حجز يتم ظهور بيانات الشاحنة المطلوبة يتم الضغط على تسجيل الدخول في حالة وجود الشاحنة داخل الميناء تظهر رسالة تفيد بذلك ولن يتم تسجيل دخول للشاحنة إذا تم تحقق الشروط من وجود حجز للشاحنة والشاحنة خارج الميناء يتم تسجيل دخولها للميناء بعد نجاح تذكرة الدخول يمكن طباعة تذكرة الدخول"]'::jsonb, '["تسجيل الشاحنة داخل الميناء إمكانية طباعة تذكرة الدخول"]'::jsonb, true),
  ('t92', 92, 'نظام إدارة البوابات', 'سناريوهات إدارة البوابات', '', 7, 'وزن بدون ربط المحاور', 'تسجيل وزن الشاحنة بدون ربطها بالمحاور', '["فتح شاشة وزن الشاحنات تحديد الشاحنة عن طريق رقمها او رقم الرحلة يتم اختيار الميزان تسجيل وزن الشاحنة"]'::jsonb, '["ظهور رسالة للمستخدم لم يتم تسجيل المحاور يجب تسجيل المحاور اولا"]'::jsonb, true),
  ('t93', 93, 'نظام إدارة البوابات', 'سناريوهات إدارة البوابات', '', 8, 'ربط محاور الشاحنة', 'ربط الشاحنة التي ستقوم بالوزن بالمحاور المحددة', '["فتح شاحنة ربط محاور الشاحنات","البحث عن الشاحنة المطلوبة عن طريقة رقمها","بعد ظهور الشاحنة يتم اختيار المحاور","اذا كانت الشاحنة تملك مقطورة يتم إضافة محاور المقطورة ايضا"]'::jsonb, '["ربط الشاحنة بالمحور لربط المقطورة بالمحور"]'::jsonb, true),
  ('t94', 94, 'نظام إدارة البوابات', 'سناريوهات إدارة البوابات', '', 9, 'وزن الشاحنة بعد ربط المحاور', 'تسجيل وزن الشاحنة بعد ربطها بالمحاور', '["فتح شاشة وزن الشاحنات تحديد الشاحنة عن طريق رقمها او رقم الرحلة يتم اختيار الميزان تسجيل الوزن الأولى في حالة انها لم تسجل من قبل تسجيل الوزن الثانية"]'::jsonb, '["تسجيل وزن الشاحنة الأولى والثانية إمكانية طباعة كارتة الميزان"]'::jsonb, true),
  ('t95', 95, 'نظام إدارة البوابات', 'سناريوهات إدارة البوابات', '', 10, 'كاشير الشاحنات', 'استعراض فاتورة الكاشير لسدادها', '["فتح شاشة كاشير الشاحنات تسجيل رقم الشاحنة او رقم الزيارة استعراض الفاتورة"]'::jsonb, '["• استعراض الفاتورة بنجاح"]'::jsonb, true),
  ('t96', 96, 'نظام إدارة البوابات', 'سناريوهات إدارة البوابات', '', 11, 'سداد الفاتورة نقدا', 'سداد فاتورة الكاشير نقدا لزيارة الشاحنة', '["فتح شاشة كاشير الشاحنات البحث عن الشاحنة استعراض الفاتورة اختيار نقطة الكاشير اختيار طريقة السداد نقدي يتم إضافة غرامة السداد النقدي 5%"]'::jsonb, '["• السداد النقدي بنجاح وإمكانية طباعة الفاتورة"]'::jsonb, true),
  ('t97', 97, 'نظام إدارة البوابات', 'سناريوهات إدارة البوابات', '', 12, 'سداد الفاتورة الكترونيا', 'سداد فاتورة الكاشير الكترونيا لزيارة الشاحنة', '["فتح شاشة كاشير الشاحنات","البحث عن الشاحنة","استعراض الفاتورة","اختيار نقطة الكاشير","اختيار طريقة السداد الالكتروني"]'::jsonb, '["• السداد الالكتروني بنجاح وإمكانية طباعة الفاتورة"]'::jsonb, true),
  ('t98', 98, 'نظام إدارة البوابات', 'سناريوهات إدارة البوابات', '', 13, 'سداد الفاتورة من رصيد العميل', 'سداد فاتورة الكاشير من رصيد العميل لزيارة الشاحنة', '["فتح شاشة كاشير الشاحنات","البحث عن الشاحنة","استعراض الفاتورة","اختيار نقطة الكاشير","اختيار طريقة السداد خصم من رصيد العميل"]'::jsonb, '["• في حالة كفاية الرصيد العميل لسداد الفاتورة يتم السداد • في حالة عدم كفاية رصيد العميل تظهر رسالة تفيد بذلك"]'::jsonb, true),
  ('t99', 99, 'نظام إدارة البوابات', 'سناريوهات إدارة البوابات', '', 14, 'خروج الشاحنة', 'تسجيل خروج الشاحنة من الميناء بعد انتهاء الاعمال الخاصة بها', '["فتح شاشة خروج الشاحنات","البحث عن الشاحنة","يجب ان تكون الشاحنة اتمت الوزن وسداد الكاشير"]'::jsonb, '["• تسجيل خروج الشاحنة من الميناء بنجاح"]'::jsonb, true),
  ('t100', 100, 'نظام إدارة البوابات', 'سناريوهات إدارة البوابات', '', 15, '.1: ساحات الانتظار', 'تسجيل دخول الشاحنة ساحة الانتظار', '["فتح شاشة دخول ساحات خارجية اختيار الميناء المطلوب البحث عن الشاحنة اختيار الساحة الخارجية تسجيل دخول الساحة الخارجية يجب ان - يجب تكون الشاحنة خارج الساحة حتى يمكن تسجيل دخولها الساحة"]'::jsonb, '["• دخول الشاحنة ساحة الانتظار"]'::jsonb, true),
  ('t101', 101, 'نظام إدارة البوابات', 'سناريوهات إدارة البوابات', '', 15, '.2: ساحات الانتظار', 'تسجيل خروج الشاحنة من ساحة الانتظار', '["فتح شاشة خروج ساحات خارجية اختيار الميناء المطلوب البحث عن الشاحنة اختيار الساحة الخارجية المتواجد بها الشاحنة تسجيل خروج الساحة الخارجية يجب ان تكون الشاحنة داخل الساحة حتى يمكن تسجيل خروجها من الساحة"]'::jsonb, '["• خروج الشاحنة من ساحة الانتظار"]'::jsonb, true),
  ('t102', 102, 'نظام إدارة المتعاملين و طلبات المستخدمين', 'سيناريوهات نظام المتعاملين و طلبات المستخدمين', '', 1, 'طلب إضافة متعامل جديد', 'التحقق من إمكانية تقديم طلب لإضافة متعامل جديد إلى النظام، من خلال إدخال بيانات المتعامل الأساسية ووسائل الاتصال المطلوبة، وبيانات الوثائق القانونية وإرفاق المستندات اللازمة لها ، ثم إرسال الطلب للمراجعة. المتطلبات: • عدم وجود متعامل مسجل مسبقًا بنفس البيانات التي تمنع التكرار(الرقم الضريي او الرقم القومي) • توفر جميع البيانات والمستندات (المرفقات) المطلوبة لإضافة المتعامل.', '["الضغط على طلب التقديم على تسجيل متعامل في شاشة تسجيل الدخول الى النظام.","الدخول إلى شاشة اضافة طلبات المتعاملين.","التحقق من ادخال الرقم الضريبي (xxx-xxx-xxx) عند اختيار نوع المتعامل شركة.","التحقق من ادخال الرقم القومي 14 رقم يبدأ ل 2 او 3 عند اختيار نوع المتعامل فرد.","استكمال باقي البيانات الأساسية للمتعامل.","الضغط على الخطوة التالية لاستكمال بيانات وسائل الاتصال المراد اضافتها للمتعامل .","الضغط على اضافة وسيلة عند الانتقال الى شاشة وسائل الاتصال .","استكمال بيانات وسائل الاتصال .","الضغط على الخطوة التالية لاستكمال بيانات الوثائق القانونية للمتعامل .","الصغط على اضافة وثيقة لاضاة بيانات الوثيقة والتحقق من رفع جميع الوثائق القانونية المعدة مسبقا لطلب المتعاملين.","مراجعة جميع البيانات والمرفقات المدخلة.","الضغط على حفظ وإرسال الطلب.","التحقق من تسجيل الطلب بنجاح وظهور رقم الطلب."]'::jsonb, '["• يتم التحقق من صحة البيانات وإلزامية الحقول المطلوبة","• يتم اراسال طلب إضافة المتعامل بنجاح","• يتم إنشاء رقم للطلب","• يظهر الطلب بالحالة المناسبة للمراجعة","• تظهر جميع بيانات المتعامل والمرفقات بشكل صحيح عند فتح الطلب ومراجعته"]'::jsonb, true),
  ('t103', 103, 'نظام إدارة المتعاملين و طلبات المستخدمين', 'سيناريوهات نظام المتعاملين و طلبات المستخدمين', '', 2, 'مراجعة طلب إضافة متعامل', 'التحقق من إمكانية مراجعة طلب إضافة متعامل جديد من خلال عرض جميع بيانات الطلب والمستندات المرفقة، والتحقق من صحتها واستيفائها للمتطلبات، ثم اتخاذ الإجراء المناسب على الطلب سواء بالقبول أو الرفض. المتطلبات: • وجود طلب إضافة متعامل تم إرساله بنجاح. • أن يكون الطلب في حالة تسمح بالمراجعة. • امتلاك المستخدم الصلاحية اللازمة لمراجعة طلبات إضافة المتعاملين.', '["تسجيل الدخول إلى النظام بحساب لديه صلاحية مراجعة طلبات المتعاملين.","الدخول إلى شاشة مراجعة طلبات المتعاملين من لوحة التحكم لمراجعة طلبات اضافة المتعاملين.","البحث عن طلب إضافة المتعامل المطلوب مراجعته.","فتح الطلب يالضغط على متابعة .","التحقق من ظهور رقم الطلب وبيانات المتعامل الأساسية.","التحقق من ظهور بيانات الوثائق القانونية وبيانات التواصل والبيانات الضريبية المسجلة بالطلب.","مراجعة المستندات والمرفقات الخاصة بالطلب.","التحقق من صحة واكتمال بيانات الطلب والمستندات.","اختيار الإجراء المناسب على الطلب.","في حالة القبول، اعتماد الطلب.","في حالة الرفض، إدخال سبب الرفض ثم رفض الطلب."]'::jsonb, '["• يتم عرض جميع بيانات طلب إضافة المتعامل بشكل صحيح وكامل","• يتمكن المستخدم من مراجعة البيانات والمستندات المرتبطة بالطلب","• عند قبول الطلب، تتغير حالة الطلب إلى مقبول ويتم تسجيل المتعامل وفقًا للإجراء المتبع","• عند رفض الطلب، تتغير حالة الطلب إلى مرفوض ويتم حفظ سبب الرفض","• لا يمكن تنفيذ إجراءات المراجعة إلا للمستخدم الذي يمتلك الصلاحية المناسبة"]'::jsonb, true),
  ('t104', 104, 'نظام إدارة المتعاملين و طلبات المستخدمين', 'سيناريوهات نظام المتعاملين و طلبات المستخدمين', '', 3, 'إضافة طلب مستخدم لإدارة حساب المتعامل', 'التحقق من إمكانية إنشاء طلب لإضافة مستخدم على حساب متعامل تم إضافته مسبقًا، بحيث يتمكن المستخدم المضاف بعد من إدارة حساب المتعامل، وإرسال الطلبات واستخدام الخدمات المخصصة للمتعامل وفقًا للصلاحيات الممنوحة له. المتطلبات: • وجود متعامل مسجل ومعتمد له رقم ضريبي مسبقًا على النظام. • توفر بيانات المستخدم المطلوب إضافته. • توفر مرفقات السجل الضريبي للمتعامل والرقم القومي للمستخدم المراد اضافته.', '["الضغط على طلب اضافة مستخدم جديد في شاشة تسجيل الدخول الى النظام.","ادخال اسم المتسخدم باللغة الانجليزية فقط مع التأكد من عدم وجود الاسم مسبقا في النظام .","استكمال البيانات الاساسية لاضافة الميتخدم مع التأكد من ادخال الرقم السري ولا يقل عن ( 8 حروف انجليزية تتكون من حرف كبير حرف صغير رمز خاص ورقم )","ادخال الرقم الضريبي للمتعامل المراد ربطه بالمستخدم مع ارفاق مستند له.","ادخال الرقم الضريبي للمستخدم مع ارفاق مستند له.","إرسال طلب إضافة المستخدم الى المراجعة وظهور رقم الطلب ."]'::jsonb, '["• يتم إنشاء طلب إضافة المستخدم وربطه بالمتعامل المحدد بنجاح","• بعد قبول الطلب، يتم تفعيل المستخدم وربطه بحساب المتعامل","• يتمكن المستخدم من الدخول إلى الشاشات والخدمات المخصصة للمتعامل أو التوكيل الملاحي","• يتمكن المستخدم من إرسال الطلبات المسموح بها وفقًا للصلاحيات المحددة","• لا يتمكن المستخدم من الوصول إلى الشاشات أو تنفيذ الإجراءات التي لا يمتلك صلاحية عليها"]'::jsonb, true),
  ('t105', 105, 'نظام إدارة المتعاملين و طلبات المستخدمين', 'سيناريوهات نظام المتعاملين و طلبات المستخدمين', '', 4, 'مراجعة طلب إضافة مستخدم', 'التحقق من إمكانية مراجعة طلب إضافة مستخدم جديد من خلال عرض جميع بيانات الطلب والمستندات المرفقة، والتحقق من صحتها واستيفائها للمتطلبات، ثم اتخاذ الإجراء المناسب على الطلب سواء بالقبول أو الرفض. المتطلبات: • وجود طلب إضافة مستخدم تم إرساله بنجاح. • أن يكون الطلب في حالة تسمح بالمراجعة. • امتلاك المستخدم الصلاحية اللازمة لمراجعة طلبات إضافة المستخدمين.', '["تسجيل الدخول إلى النظام بحساب لديه صلاحية مراجعة طلبات اضافة المستخدمبن.","الدخول إلى شاشة مراجعة طلبات المستخدمين من لوحة التحكم لمراجعة طلبات المستخدمين.","البحث عن طلب إضافة المستخدم المطلوب مراجعته.","فتح الطلب يالضغط على متابعة .","التحقق من ظهور رقم الطلب وبيانات المستخدم الأساسية.","التحقق من ظهور بيانات الطلب والمرفقات المسجلة بالطلب.","مراجعة المستندات والمرفقات الخاصة بالطلب.","التحقق من صحة واكتمال بيانات الطلب والمستندات.","اختيار الإجراء المناسب على الطلب.","في حالة القبول، اعتماد الطلب وتحديد صلاحيات او دور المستخدم","في حالة الرفض، إدخال سبب الرفض ثم رفض الطلب."]'::jsonb, '["• تظهر جميع بيانات طلب إضافة المستخدم والمتعامل المرتبط به بشكل صحيح","• يتمكن المراجع من مراجعة بيانات المستخدم والصلاحيات المطلوبة","• عند اعتماد الطلب، يتم إنشاء/تفعيل المستخدم وربطه بحساب المتعامل وفقًا للصلاحيات المعتمدة","• عند رفض الطلب، تتغير حالة الطلب إلى مرفوض ويتم حفظ سبب الرفض","• لا يمكن تنفيذ إجراءات المراجعة إلا للمستخدم الذي يمتلك الصلاحية المناسبة"]'::jsonb, true),
  ('t106', 106, 'نظام إدارة المتعاملين و طلبات المستخدمين', 'سيناريوهات نظام المتعاملين و طلبات المستخدمين', '', 5, 'طلب مزاولة نشاط لمتعامل', 'التحقق من إمكانية تقديم طلب لمزاولة نشاط لمتعامل مسجل مسبقًا بالنظام، من خلال اختيار النشاط المطلوب وإدخال البيانات المطلوبة وإرفاق المستندات اللازمة، ثم إرسال الطلب للمراجعة والاعتماد. المتطلبات: • وجود متعامل مسجل ومعتمد مسبقًا على النظام. • وجود أنشطة متاحة يمكن للمتعامل التقدم لمزاولتها. • توفر البيانات والمستندات المطلوبة لمزاولة النشاط. • امتلاك المستخدم الصلاحية اللازمة لتقديم طلب مزاولة النشاط. • امكانية ارسال طلبات مزاولة النشط لا تظهر الا مستخدمي المتعاملين.', '["تسجيل الدخول إلى النظام بحساب المستخدم الذي تم ربطه بالمتعامل.","التحقق من اختيار ميناء محدد لاضافة طلب مزاولة نشاط في الميناء المحدد.","الدخول إلى شاشة طلبات مزاولة النشاط يالضغط على علامة المستخدم الموجودة في يسار الشاشة.","اختيار نوع الطلب اول مرة اذا كان النساط غير موجود مسبقا للمتعامل.","اختيار نوع الطلب تجديد اذا كان النشاط موجود مسبقا للمتعامل وتم انتهاء فترة مزاولة النشاط.","اختيار النشاط المطلوب مزاولته.","ادخال تاريخ بداية مزاولة النشاط.","إدخال البيانات الإضافية المطلوبة حسب نوع النشاط.","التحقق من رفع المستندات الالزامية المطلوبة .","مراجعة بيانات الطلب والمرفقات.","إرسال طلب مزاولة النشاط.","التحقق من تسجيل الطلب بنجاح وظهور رقم الطلب وحالته."]'::jsonb, '["• يتم التحقق من استيفاء البيانات والحقول الإلزامية","• يتم حفظ طلب مزاولة النشاط بنجاح","• يتم إنشاء رقم للطلب","• يظهر الطلب بالحالة المناسبة للمراجعة","• تظهر بيانات النشاط والمرفقات المرتبطة بالطلب بشكل صحيح","• لا يتم اعتبار النشاط معتمدًا أو متاحًا للمتعامل إلا بعد استكمال إجراءات المراجعة والاعتماد"]'::jsonb, true),
  ('t107', 107, 'نظام إدارة المتعاملين و طلبات المستخدمين', 'سيناريوهات نظام المتعاملين و طلبات المستخدمين', '', 6, 'مراجعة طلب مزاولة نشاط لمتعامل', 'التحقق من إمكانية مراجعة طلب مزاولة نشاط مقدم من متعامل مسجل بالنظام، من خلال مراجعة بيانات المتعامل والنشاط والمستندات المرفقة، ثم اتخاذ الإجراء المناسب بقبول أو رفض الطلب. المتطلبات: • وجود متعامل مسجل ومعتمد بالنظام. • وجود طلب مزاولة نشاط مقدم من المتعامل. • أن يكون الطلب في حالة تسمح بالمراجعة. • امتلاك المستخدم صلاحية مراجعة طلبات مزاولة النشاط.', '["تسجيل الدخول إلى النظام بحساب لديه صلاحية مراجعة طلبات مزاولة النشاط.","الدخول إلى شاشة مراجعة طلبات مزاولة النشاط / طلبات التراخيص.","البحث عن طلب مزاولة النشاط المطلوب مراجعته.","فتح الطلب بالضغط على متابغعة.","التحقق من ظهور بيانات الطلب بشكل صحيح.","مراجعة النشاط المطلوب مزاولته.","مراجعة البيانات المرتبطة بالنشاط.","مراجعة المستندات والمرفقات المقدمة مع الطلب.","التحقق من استيفاء الطلب للبيانات والمستندات المطلوبة.","اختيار الإجراء المناسب على الطلب.","في حالة استيفاء المتطلبات، قبول الطلب وتحديد فترة البداية والنهاية لمزاولة النشاط.","في حالة عدم استيفاء المتطلبات، رفض الطلب وإدخال سبب الرفض."]'::jsonb, '["• تظهر بيانات المتعامل والنشاط والمرفقات بشكل صحيح","• يتمكن المراجع من التحقق من استيفاء متطلبات مزاولة النشاط","• عند اعتماد الطلب، تتغير حالة الطلب إلى مقبول ويصبح النشاط متاحًا للمتعامل وفقًا للإجراءات المحددة","• عند رفض الطلب، تتغير حالة الطلب إلى مرفوض ويتم حفظ سبب الرفض"]'::jsonb, true),
  ('t108', 108, 'نظام إدارة المتعاملين و طلبات المستخدمين', 'سيناريوهات نظام المتعاملين و طلبات المستخدمين', '', 7, 'إضافة طلب تحديث بيانات متعامل', 'التحقق من إمكانية تقديم طلب لتحديث بيانات متعامل مسجل مسبقًا بالنظام، من خلال تعديل البيانات المطلوب تحديثها وإرفاق المستندات الداعمة عند الحاجة، ثم إرسال الطلب للمراجعة والاعتماد. المتطلبات: • وجود متعامل مسجل ومعتمد مسبقًا بالنظام. • وجود صلاحية لتقديم طلب تحديث بيانات المتعامل. • توفر البيانات الجديدة والمستندات المطلوبة للتحديث، إن وجدت.', '["تسجيل الدخول إلى النظام.","الضغط على قائمة المستخدم.","اختيار طلب تحديث بيانات متعامل.","تعديل البيانات المطلوبة مع التأكد من عدم امكانية تعديل الرقم الضريبي او الرقم القومي للمتعامل.","الضغط على حفظ والرسال اذا كان التعديل في بيانات المتعامل الاساسية فقط .","الضغط على الخطوة التالية اذا كان التعديل في بيانات وسائل الاتصال للمتعامل.","اضافة البيانات الجديدة المطلوبة في وسائل الاتصال ثم الضغط على حفظ وارسال اذا كان التحديث المطلوب في شاشة وسائل الاتصال .","الضغط على الخطوة التالية اذا كان التحديث المطلوب في شاشة الوثائق القانونية","اضافىة البيانات الجديدة المطلوبة في الوثائق القانونية والتحقق من رفع المستندات الالزامية ثم الضغط على حفظ وارسال.","مراجعة البيانات الجديدة والمرفقات.","إرسال طلب تحديث البيانات.","التحقق من تسجيل الطلب وظهور رقم الطلب وحالته."]'::jsonb, '["• يتم عرض بيانات المتعامل الحالية بشكل صحيح","• يتمكن المستخدم من اضافة البيانات المسموح بتحديثها","• يتم التحقق من الحقول الإلزامية وصحة البيانات المدخلة","• يتم حفظ طلب تحديث البيانات بنجاح","• يتم إنشاء رقم للطلب","• يظهر الطلب بالحالة المناسبة للمراجعة","• لا يتم تحديث بيانات المتعامل الأساسية فعليًا إلا بعد قبول الطلب"]'::jsonb, true),
  ('t109', 109, 'نظام إدارة المتعاملين و طلبات المستخدمين', 'سيناريوهات نظام المتعاملين و طلبات المستخدمين', '', 8, 'مراجعة طلب تحديث بيانات متعامل', 'التحقق من إمكانية مراجعة طلب تحديث بيانات متعامل مسجل مسبقًا بالنظام، من خلال مراجعة البيانات الحالية والبيانات المطلوب تحديثها والمستندات الداعمة، ثم اتخاذ الإجراء المناسب على الطلب. المتطلبات: • وجود متعامل مسجل ومعتمد مسبقًا بالنظام. • وجود طلب تحديث بيانات مقدم من المتعامل. • أن يكون الطلب في حالة تسمح بالمراجعة. • امتلاك المستخدم الصلاحية اللازمة لمراجعة طلبات تحديث بيانات المتعاملين.', '["تسجيل الدخول إلى النظام بحساب لديه صلاحية مراجعة طلبات تحديث بيانات المتعاملين.","الدخول إلى شاشة مراجعة طلبات المتعاملين من خلال لوحة التحكم .","البحث عن طلب تحديث بيانات المتعامل المطلوب مراجعته.","فتح الطلب من خلال الضغط على متابعة.","التحقق من ظهور بيانات المتعامل الحالية.","مراجعة البيانات الجديدة المطلوب تحديثها ومقارنتها بالبيانات الحالية.","مراجعة المستندات والمرفقات الداعمة للتحديث، إن وجدت.","التحقق من صحة واكتمال البيانات والمستندات المطلوبة.","اختيار الإجراء المناسب على الطلب.","في حالة استيفاء المتطلبات، قبول طلب التحديث.","في حالة عدم استيفاء المتطلبات، رفض الطلب مع إدخال سبب الرفض."]'::jsonb, '["• تظهر بيانات المتعامل الحالية والبيانات المضافة من خلال طلب التحديث بشكل صحيح","• يتمكن المراجع من مراجعة التغييرات والمستندات الداعمة","• عند اعتماد الطلب، يتم تحديث بيانات المتعامل بالبيانات المعتمدة","• عند رفض الطلب، تظل بيانات المتعامل الحالية دون تغيير ويتم حفظ سبب الرفض","• تتغير حالة الطلب وفقًا للإجراء الذي تم اتخاذه"]'::jsonb, true),
  ('t110', 110, 'نظام إدارة البضائع العامة', 'سناريوهات الإعدادات والبيانات الأساسية', '', 1, 'اضافة البيانات الاساسية', 'اضافة البيانات الاساسية التي سيتم استخدامها بالنظام فيما بعد ويتم تعريفها اول ومرة ويتم اضافتها في حالة استحداث بيانات اساسية جديدة', '["الدخول على شاشة البيانات الاساسية","اختيار شاشة البيان الاساسي","الضغط على مفتاح الاضافة","يتم تسجيل البيانات المطلوبة للاضافة","في حالة وجود بيانات اساسية غير مدرجة تظهر رسالة تفيد بذلك","بعد الانتهاء من تسجيل البيانات يتم الضغط على مفتاح الحفظ"]'::jsonb, '["• حفظ البيان الاساسي • امكانية استخدام البيان في النظام فور الحفظ"]'::jsonb, true),
  ('t111', 111, 'نظام إدارة البضائع العامة', 'سناريوهات الإعدادات والبيانات الأساسية', '', 2, 'تعديل البيانات الاساسية', 'تعديل البيانات الاساسية التي تم تعريفها مسبقا', '["الدخول على شاشة البيانات الاساسية","اختيار شاشة البيان الاساسي","الضغط على مفتاح التعديل","يتم تعديل البيانات المطلوبة","لا يمكن تعديل بعض البيانات في حالة استخدام البيان الاساسي بالنظام","بعد الانتهاء من تعديل البيانات يتم الضغط على مفتاح الحفظ"]'::jsonb, '["• حفظ التعديل • امكانية استخدام البيان في النظام فور حفظ التعديل"]'::jsonb, true),
