  ('t151', 151, 'نظام إدارة البضائع العامة', 'سيناريوهات دورة عمل إدارة القطار', '', 3, 'الوصول الفعلي والمغادرة الفعلية للقطار', 'تسجيل التاريخ الفعلي للوصول والمغادرة', '["الدخول على شاشة الوصول والمغادرة الفعلية للقطار","البحث عن الزيارة المطلوبة","الضغط على ايقونة الاجراءات","في حالة عدم تسجيل الوصول الفعلي يتم تسجيل الوصول الفعلي وتاريخ بدء العمل","لتسجيل المغادرة الفعلية يجب الضغط ايقونة الاجراءات لكن يجب ان تكون الزيارة سجلت تاريخ وصول ثم يتم تسجيل المغادرة الفعلية وتاريخ الانتهاء من العمل"]'::jsonb, '["• تسجيل الوصول الفعلي والمغادرة الفعلية"]'::jsonb, true),
  ('t152', 152, 'نظام الفواتير', 'سناريوهات الإعدادات والبيانات الأساسية', '', 1, 'إضافة ورديات في النظام', 'التحقق من إمكانية تعريف وربط الورديات بإدارات الميناء، بحيث يتم تحديد الورديات التي تعمل خلالها كل إدارة وفقًا لنظام العمل المعتمد. التحقق من إمكانية ربط الورديات المضافة بنوع الفاتورة لاستخدامها ضمن عمليات الفوترة.', '["الدخول إلى نظام الفواتير","الدخول الى شاشة الاعدادات الدخول إلى شاشة الورديات/ المواقبت","التأكد من اختيار ميناء محددة","الضغط على زر اضافة","استكمال البيانات المطلوبة","الضغط على علامة زر الحفظ"]'::jsonb, '["• يتم إضافة الوردية بنجاح وربطها بالإدارة المحددة","• يتم إضافة الوردية وربطها بنوع الفاتورة بنجاح","• تظهر الوردية ضمن الورديات المرتبطة بنوع الفاتورة","• لا تظهر الورديات غير المرتبطة بنوع الفاتورة ضمن الاختيارات الخاصة به","• يتم استخدام الورديات المعرفة للإدارة عند تنفيذ العمليات المرتبطة بمواعيد العمل"]'::jsonb, true),
  ('t153', 153, 'نظام الفواتير', 'سناريوهات الإعدادات والبيانات الأساسية', '', 2, 'تعريف أيام الإجازات للميناء .', 'التحقق من إمكانية تعريف أيام الإجازات الرسمية للميناء وتحديد الفترات التي لا يتم خلالها احتساب أو تنفيذ الخدمات وفقًا لقواعد العمل المعتمدة.', '["تسجيل الدخول إلى نظام الفواتير.","الدخول إلى «الاعدادات».","الدخول إلى شاشة الاجازات/ المواقبت.","التأكد من اختيار ميناء محددة .","الضغط على اليوم المراد تحديده كاجازة مرتين .","تحديد اسم الإجازة وبياناتها المطلوبة.","حفظ بيانات الإجازة."]'::jsonb, '["• يتم حفظ يوم الإجازة بنجاح","• يظهر يوم الإجازة ضمن الأيام المعرفة للميناء","• يمكن تعريف أكثر من يوم إجازة","• يتم التعامل مع اليوم المُعرّف كإجازة عند تطبيق قواعد النظام المرتبطة بأيام عمل الميناء"]'::jsonb, true),
  ('t154', 154, 'نظام الفواتير', 'سناريوهات الإعدادات والبيانات الأساسية', '', 3, 'منع تعديل إجازة في تاريخ سابق', 'التحقق من عدم إمكانية تعديل بيانات إجازة سبق تحديدها في تاريخ سابق، حفاظًا على صحة البيانات التاريخية للميناء.', '["تسجيل الدخول إلى النظام.","الدخول إلى «الاعدادات».","الدخول إلى شاشة الاجازات/ المواقبت.","البحث عن إجازة مسجلة بتاريخ سابق.","محاولة تعديل بيانات الإجازة.","محاولة حفظ التعديلات."]'::jsonb, '["• يمنع النظام تعديل الإجازة المسجلة بتاريخ سابق","• لا يتم حفظ أي تغييرات على بيانات الإجازة","• تظهر رسالة توضح عدم إمكانية تعديل إجازة بتاريخ سابق","• تظل البيانات التاريخية للإجازة كما تم تسجيلها سابقًا"]'::jsonb, true),
  ('t155', 155, 'نظام الفواتير', 'سناريوهات الإعدادات والبيانات الأساسية', '', 4, 'تعريف مواعيد الشروق والغروب لكل ميناء', 'التحقق من إمكانية تعريف مواعيد الشروق والغروب لكل ميناء، بحيث يتم استخدام هذه المواعيد في تحديد فترات العمل والعمليات المرتبطة بالميناء.', '["تسجيل الدخول إلى النظام.","الدخول إلى شاشة الاعدادات","الدخول الى شاشة المواقيت .","الدخول الى شاشة الشروق والغروب","اختيار الميناء المطلوب تعريف مواعيد الشروق والغروب له.","الضغط على اليوم المراد تحديد مواعيد الشروق والغروب له .","تحديد وقت الشروق.","تحديد وقت الغروب.","حفظ البيانات."]'::jsonb, '["• يتم حفظ وقت الشروق والغروب للميناء بنجاح","• يظهر وقت الشروق والغروب عند استعراض بيانات الميناء","• يمكن تعريف مواعيد مختلفة لكل ميناء وفقًا للمواعيد المعتمدة له","• يتم استخدام المواعيد المعرفة للميناء في العمليات التي تعتمد على أوقات الشروق والغروب"]'::jsonb, true),
  ('t156', 156, 'نظام الفواتير', 'سناريوهات الإعدادات والبيانات الأساسية', '', 5, 'إضافة السنوات المالية في النظام', 'التحقق من إمكانية تعريف السنوات المالية في النظام وتحديد الفترة الزمنية لكل سنة مالية، لاستخدامها في العمليات المالية والفواتير.', '["تسجيل الدخول إلى النظام.","الدخول الى شاشة الاعدادت","الدخول إلى شاشة السنوات المالية.","إضافة سنة مالية جديدة.","تحديد السنة المالية وتاريخ بداية السنة وتاريخ نهايتها.","حفظ بيانات السنة المالية.","إعادة فتح شاشة السنوات المالية والتحقق من ظهور السنة المضافة.","إضافة سنة مالية أخرى والتحقق من إمكانية تعريف أكثر من سنة مالية."]'::jsonb, '["• يتم إضافة السنة المالية بنجاح","• يتم حفظ تاريخ بداية ونهاية السنة المالية بشكل صحيح","• تظهر السنة المالية ضمن السنوات المعرفة في النظام","• يمكن تعريف أكثر من سنة مالية","• يتم استخدام السنة المالية الصحيحة في العمليات والفواتير وفقًا للفترة الزمنية المحددة لها"]'::jsonb, true),
  ('t157', 157, 'نظام الفواتير', 'سناريوهات الإعدادات والبيانات الأساسية', '', 6, 'إضافة سعر صرف للعملة الأجنبية في النظام', 'التحقق من إمكانية تعريف سعر صرف للعملات الأجنبية مقابل العملة المحلية، لاستخدام سعر الصرف المعتمد في العمليات والفواتير التي تتعامل مع العملات الأجنبية.', '["تسجيل الدخول إلى النظام.","الدخول إلى شاشة اسعار صرف العملات / البيانات المالية.","اختيار العملة الأجنبية المطلوب تعريف سعر صرف لها.","تحديد تاريخ سريان سعر الصرف.","إدخال سعر صرف العملة مقابل العملة المحلية.","حفظ بيانات سعر الصرف.","إعادة فتح شاشة أسعار الصرف والتحقق من ظهور السعر المضاف.","إجراء عملية مالية أو إصدار فاتورة باستخدام العملة الأجنبية للتحقق من تطبيق سعر الصرف المعرّف."]'::jsonb, '["• يتم إضافة سعر صرف العملة الأجنبية بنجاح","• يتم حفظ سعر الصرف مع تاريخ السريان المحدد","• يظهر سعر الصرف ضمن أسعار العملة المعرفة بالنظام","• يتم استخدام سعر الصرف المعتمد عند إجراء العمليات أو إصدار الفواتير بالعملة الأجنبية","• يتم احتساب القيمة بالعملة المحلية وفقًا لسعر الصرف المعرّف"]'::jsonb, true),
  ('t158', 158, 'نظام الفواتير', 'سناريوهات الإعدادات والبيانات الأساسية', '', 7, 'تعريف الخصومات في النظام', 'التحقق من إمكانية تعريف الخصومات في النظام وتحديد بيانات وقواعد الخصم، بحيث يمكن استخدامها عند احتساب قيمة الفواتير وفقًا للقواعد المعتمدة.', '["تسجيل الدخول إلى النظام.","الدخول إلى شاشة الخصومات/ البيانات الاساسية .","إضافة خصم جديد.","تحديد الجهة والادارة المنوطة بالخصم .","إدخال بيانات الخصم المطلوبة.","تحديد نوع وقيمة الخصم وفقًا لقواعد النظام.","حفظ بيانات الخصم.","إعادة فتح شاشة الخصومات والتحقق من ظهور الخصم المضاف.","استخدام الخصم في فاتورة تابعة لنفس الجهة والادارة .","التحقق من تطبيق الخصم واحتسابه ضمن إجمالي الفاتورة."]'::jsonb, '["• يتم تعريف الخصم وحفظ بياناته بنجاح","• يظهر الخصم ضمن الخصومات المعرفة في النظام","• يتم تطبيق الخصم فقط على الفواتير أو البنود التي تنطبق عليها شروطه","• يتم احتساب قيمة الخصم بشكل صحيح وفقًا للقيمة أو النسبة المحددة","• يتم تحديث إجمالي الفاتورة بعد تطبيق الخصم وفقًا لقواعد النظام"]'::jsonb, true),
  ('t159', 159, 'نظام الفواتير', 'سناريوهات الإعدادات والبيانات الأساسية', '', 8, 'إضافة نوع فاتورة جديد للنظام', 'إضافة نوع فاتورة جديد واستكمال البيانات المطلوبة وحفظه.', '["تسجيل الدخول إلى نظام الفواتير.","الدخول إلى شاشة انواع الفواتير الموجودة في تعريف الفواتير.","الضغط على «إضافة».","إدخال بيانات نوع الفاتورة المطلوبة .","استكمال جميع الحقول الإلزامية والتحقق من اختيار الفاتورة الاب ونوع الطلب عند اختيار وضع الفاتوةر تسميح مالي.","الضغط على «حفظ»."]'::jsonb, '["• يتم حفظ نوع الفاتورة بنجاح","• يظهر نوع الفاتورة في قائمة أنواع الفواتير","• يمكن استخدام نوع الفاتورة في العمليات المرتبطة به"]'::jsonb, true),
  ('t160', 160, 'نظام الفواتير', 'سيناريوهات تعريف الفواتير', '', 1, 'إضافة مجموعة جديدة لنوع الفاتورة', 'إضافة مجموعة جديدة وربطها بنوع فاتورة محدد.', '["تسجيل الدخول إلى نظام الفواتير.","الدخول إلى شاشة انواع الفواتير الموجودة في تعريف الفواتير.","اختيار نوع الفاتورة المطلوبوالضغط على زر تعديل الفاتورة.","الضغط على زر «إضافة مجموعة».","إدخال بيانات المجموعة المطلوبة.","استكمال الحقول الإلزامية والتأكد من وجود متغيرات الشرط ومتغيرات الحساب اذا لزم الامر .","الضغط على «✓. » لحفظ مجموعة الفاتورة."]'::jsonb, '["• يتم حفظ المجموعة بنجاح","• يتم ربط المجموعة بنوع الفاتورة المحدد","• تظهر المجموعة ضمن مجموعات نوع الفاتورة","• يمكن استخدام المجموعة في تعريف البنود والخدمات المرتبطة بنوع الفاتورة"]'::jsonb, true),
  ('t161', 161, 'نظام الفواتير', 'سيناريوهات تعريف الفواتير', '', 2, 'إضافة أكثر من مجموعة لنفس نوع الفاتورة', 'إضافة عدة مجموعات إلى نفس نوع الفاتورة.', '["اختيار نوع الفاتورة والضغط على زر تعديل نوع الفاتورة لاضافة مجموعات الفاتورة .","إضافة بيانات المجموعة الأولى.","التركيز على ان مستوى المجموعة (ترتيب المجمموعة ) يجب ان يكون مميز لمجموعات نوع الفاتورة ولا يجب تكراره لمجموعات نوع الفاتورة الاخرى.","حفظ المجموعة الاولى بالضغط على علامة ✓","الضغط مرة اخرى على زر اضافة مجموعة لاضافة مجموعة جديدة .","إضافة بيانات المجموعة الثانية.","حفظ المجموعة الثانية بالضغط على علامة ✓"]'::jsonb, '["• يتم حفظ جميع المجموعات بنجاح","• تظهر جميع المجموعات تحت نوع الفاتورة الصحيح","• لا يتم ربط المجموعات بنوع فاتورة آخر","• يمكن لكل مجموعة أن تحتوي على البنود أو الخدمات الخاصة بها"]'::jsonb, true),
  ('t162', 162, 'نظام الفواتير', 'سيناريوهات تعريف الفواتير', '', 3, 'حذف مجموعة من نوع الفاتورة .', 'التحقق من إمكانية إزالة مجموعة مرتبطة بنوع الفاتورة', '["اختيار نوع الفاتورة.","الانتقال إلى قسم «المجموعات».","إلغاء تحديد المجموعة المطلوبة.","الضغط على «حفظ»."]'::jsonb, '["• يتم إزالة ارتباط المجموعة بنوع الفاتورة","• لا تظهر المجموعة ضمن المجموعات المرتبطة بنوع الفاتورة","• لا تتأثر المجموعات الأخرى المرتبطة بنوع الفاتورة"]'::jsonb, true),
  ('t163', 163, 'نظام الفواتير', 'سيناريوهات تعريف الفواتير', '', 4, 'حذف مجموعة غير مستخدمة من نوع الفاتورة', 'التحقق من إمكانية إزالة مجموعة مرتبطة بنوع الفاتورة في حالة عدم ارتباطها بأي بنود وعدم استخدامها في فاتورة صادرة.', '["الدخول إلى نظام الفواتير.","الدخول إلى «تعريف الفواتير».","الدخول إلى شاشة «انواع الفواتير».","اختيار نوع الفاتورة المطلوب والضغط على زر التعديل .","اختيار مجموعة مرتبطة بنوع الفاتورة.","التأكد من عدم ارتباط المجموعة بأي بنود.","التأكد من عدم استخدام المجموعة في أي فاتورة مصدرة.","الصغط على زر حذف المجموعة .","يتم حفظ المجموعة بنجاح ."]'::jsonb, '["• يتم حذف المجموعة من نوع الفاتورة بنجاح","• لا تظهر المجموعة ضمن المجموعات المرتبطة بنوع الفاتورة","• لا تتأثر باقي المجموعات المرتبطة بنوع الفاتورة"]'::jsonb, true),
  ('t164', 164, 'نظام الفواتير', 'سيناريوهات تعريف الفواتير', '', 5, 'منع حذف مجموعة مستخدمة', 'التحقق من منع إزالة مجموعة مرتبطة بنوع الفاتورة في حالة ارتباطها ببنود أو استخدامها في فاتورة مصدرة.', '["الدخول إلى نظام الفواتير.","الدخول إلى «تعريف الفواتير».","الدخول إلى شاشة «انواع الفواتير».","اختيار نوع الفاتورة المطلوب والضغط على زر التعديل .","اختيار مجموعة مرتبطة بنوع الفاتورة.","التأكد من عدم ارتباط المجموعة بأي بنود.","التأكد من عدم استخدام المجموعة في أي فاتورة مصدرة.","الصغط على زر حذف المجموعة .","لا يتم حذف المجموعة مع ظهور رسالة تحذيرية \" لا يمكن الحذف هذه المجموعة مرتبطة ببيانات اخرى\""]'::jsonb, '["• لا يسمح النظام بإزالة المجموعة","• تظل المجموعة مرتبطة بنوع الفاتورة","• تظهر رسالة توضح سبب عدم إمكانية الإزالة، لا يمكن الحذف هذه المجموعة مرتبطة ببيانات اخرى"]'::jsonb, true),
  ('t165', 165, 'نظام الفواتير', 'سيناريوهات تعريف الفواتير', '', 9, 'منع حذف نوع الفاتورة المرتبط بمجموعات أو المستخدم في فاتورة مصدرة من قبل', 'التحقق من عدم إمكانية حذف نوع الفاتورة في حالة وجود مجموعات مرتبطة به أوتم اصدارها من قبل .', '["الدخول إلى نظام الفواتير.","الدخول إلى «تعريف الفواتير».","الدخول إلى شاشة «نوع الفاتورة».","اختيار نوع فاتورة مرتبط بمجموعة واحدة أو أكثر.","محاولة حذف نوع الفاتورة بالضغط على زر الحذف . حالة أخرى:","ختيار نوع فاتورة تم استخدامه في فاتورة مصدرة.","محاولة حذف نوع الفاتورة."]'::jsonb, '["• لا يسمح النظام بحذف نوع الفاتورة طالما توجد مجموعات مرتبطة به","• يظل نوع الفاتورة موجودًا في النظام","• لا يسمح النظام بحذف نوع الفاتورة طالما تم استخدامه في فاتورة مصدرة","• تظل البيانات والارتباطات السابقة محفوظة"]'::jsonb, true),
  ('t166', 166, 'نظام الفواتير', 'سيناريوهات تعريف الفواتير', '', 10, 'إضافة التوقيعات المراد ظهورها في تقرير الفاتورة', 'التحقق من إمكانية إضافة وتحديد التوقيعات التي يراد ظهورها في تقرير الفاتورة.', '["الدخول إلى نظام الفواتير.","الدخول إلى «تعريف الفواتير».","الدخول إلى شاشة «انوع الفواتير».","اختيار نوع الفاتورة المطلوب.","الصغط على زر تعديل نوع افاتورة .","الضغط على زر الخطوة التالية للانتقال الي الامضاءات .","اضافة الامضاءات او التوقيعات المراد ظهورها في تقرير الفاتورة.","الضغط على حفظ."]'::jsonb, '["• يتم حفظ التوقيعات المحددة بنجاح","• تظهر التوقيعات المحددة في تقرير الفاتورة","• تظهر التوقيعات بالترتيب والتنسيق المحدد في تعريف نوع الفاتورة","• لا تظهر أي توقيعات لم يتم تحديدها لنوع الفاتورة"]'::jsonb, true),
  ('t167', 167, 'نظام الفواتير', 'سيناريوهات تعريف الفواتير', '', 11, 'التحقق من وجود قرارات الفاتورة قبل إضافة البنود', 'التحقق من أن النظام يتأكد من وجود قرارات مرتبطة بنوع الفاتورة قبل السماح بإضافة البنود.', '["الدخول إلى نظام الفواتير.","الدخول إلى «تعريف الفواتير».","الدخول إلى شاشة «قرارات انواع الفواتير».","اختيار نوع الفاتورة المراد ربطها بالقرار .","ادخال بيانات القرار المراد اضافته .","التأكد من اضافة قيم الزيادة السنوية بالعملة المصري والعملة الاجنبي .","الضغط على زر الحفظ ."]'::jsonb, '["• يتحقق النظام من وجود قرار فاتورة مرتبط بنوع الفاتورة قبل إضافة البنود ويتم ظهور القرارات المضافة عند اضافة بنود الفاتورة","• في حالة عدم وجود قرار فاتورة، لا يسمح النظام بإضافة البنود","• تظهر رسالة توضح ضرورة إضافة قرار فاتورة أولًا","• في حالة وجود قرار فاتورة، يسمح النظام بإضافة البنود المتاحة وفقًا للقرار"]'::jsonb, true),
  ('t168', 168, 'نظام الفواتير', 'سيناريوهات تعريف الفواتير', '', 12, 'إضافة أكثر من قرار لنفس نوع الفاتورة', 'التحقق من إمكانية إضافة وربط أكثر من قرار بنفس نوع الفاتورة.', '["الدخول إلى نظام الفواتير.","الدخول إلى «تعريف الفواتير».","الدخول إلى شاشة «قرارات انواع الفواتير».","الضغط على زر اضافة واختيار نوع الفاتورة المطلوب.».","إضافة القرار الأول وربطه بنوع الفاتورة.","إضافة قرار آخر لنفس نوع الفاتورة.","حفظ البيانات."]'::jsonb, '["• يتم حفظ القرارات المرتبطة بنوع الفاتورة بنجاح","• لا يمكن ربط أكثر من قرار بنفس نوع الفاتورة لكن يظهر امكانية الاختيار من بين القرارات المرتبطة بنوع الفاتورة","• تظهر جميع القرارات المرتبطة ضمن قائمة قرارات نوع الفاتورة","• يمكن استخدام القرارات المرتبطة وفقًا لقواعد الفوترة المعتمدة"]'::jsonb, true),
  ('t169', 169, 'نظام الفواتير', 'سيناريوهات تعريف الفواتير', '', 12, 'إضافة البنود إلى نوع الفاتورة', 'التحقق من إمكانية إضافة البنود المسموح بها إلى نوع الفاتورة وربطها به لاستخدامها عند تكويد الفواتير.', '["الدخول إلى نظام الفواتير.","الدخول إلى «تعريف الفواتير».","الدخول إلى شاشة «البنود».","الضغط على زر اضافة .","اختيار نوع الفاتورة .","اختيار مجموعة من مجموعات الفاتورة لربطها بالبند المراد اضافته .","ادخال اسم البند .","استكمال بيانات البند .","اختيار قرار من قرارات الفاتورة المضاف مسبقا .","الضغط على حفظ .","الضغط على الخطوة التالية للانتقال الى اضافة طريقة حساب البند طبقا لمتغيرات الحساب المضافة مسبقا لمجموعات الفاتورة ."]'::jsonb, '["• يتم إضافة البند الى مجموعة نوع الفاتورة","• يظهر البند ضمن البنود المرتبطة بنوع الفاتورة","• لا تظهر البنود غير المرتبطة بنوع الفاتورة ضمن البنود المتاحة للتكويد"]'::jsonb, true),
  ('t170', 170, 'نظام الفواتير', 'سيناريوهات تعريف الفواتير', '', 13, 'إضافة طريقة حساب للبند', 'التحقق من إمكانية إضافة طريقة الحساب المطلوبة، وربطها بالبند المستخدم ضمن نوع الفاتورة.', '["الدخول إلى نظام الفواتير.","الدخول إلى «تعريف الفواتير».","الدخول إلى شاشة «البنود».","اختيار البند المراد تعريفه والضغط على زر تعديل البند .","الانتقال إلى بيانات البند.","الضغط على الخطوة التالية للانتقال الى طريقة حساب البند .","اختيار طريقة الحساب المناسبة للبند:-","قيمة ثابتة : قيمة موحدة ومعرفة للبند .","قيمة متغيرة : يتم حسابها بناءً على متغيرات الحساب المضافة سابقا لمجموعة الفاتورة .","بند نهائي : عند تفعيل مربع تحديد بند نهائي يتم حساب البند طبقا للبنود المضافة مسبقا في الفاتورة .","استكمال البيانات والحفظ ."]'::jsonb, '["• يتم حفظ طريقة الحساب المحددة للبند بنجاح","• يتم ربط طريقة الحساب بالبند","• يتم تطبيق طريقة الحساب المحددة عند استخدام البند في اصدار الفاتورة","• لا تظهر أو تتاح طرق الحساب والحالات غير المرتبطة بالبند وفقًا لقواعد النظام"]'::jsonb, true),
  ('t171', 171, 'نظام الفواتير', 'سيناريوهات تعريف الفواتير', '', 14, 'إضافة حالات للبند', 'التحقق من إمكانية إضافة حالات البنود، وربطها بالبند المستخدم ضمن نوع الفاتورة.', '["الدخول إلى نظام الفواتير.","الدخول إلى «تعريف الفواتير».","الدخول إلى شاشة «البنود».","اختيار البند المراد تعريفه والضغط على زر تعديل البند .","الانتقال إلى بيانات البند.","الضغط على الخطوة التالية للانتقال الى طريقة حساب البند .","الضغط على الخطوة التالية للانتقال الى حالات البند .","الضغط على اضافة لاضافة الحالات .","استكمال البيانات المطلوبة وتحديد حالات البند طبقا لنتغيرات الشرط المضافة مسبقا لمجموعة الفاتورة ."]'::jsonb, '["• يتم حفظ الحالات المحددة للبند بنجاح","• يتم ربط الحالات المضافة بالبند","• يتم تطبيق طريقة الحساب المحددة عند تطبيق او ظهور حالات البند عند استخدام البند في اصدار الفاتورة","• لا تظهر أو تتاح الحالات غير المرتبطة بالبند وفقًا لقواعد النظام"]'::jsonb, true),
  ('t172', 172, 'نظام الفواتير', 'سيناريوهات تعريف الفواتير', '', 15, 'تعريف نطاق المتغير', 'التحقق من إمكانية تعريف نطاق للقيم المسموح بها للمتغير المرتبط بالبند، بما يضمن استخدام قيم المتغير ضمن الحدود المحددة عند احتساب قيمة البند.', '["تسجيل الدخول إلى النظام.","الدخول إلى شاشة تعريف الفواتير.","اختيار البند المطلوب.","الدخول إلى متغيرات بنود الفاتورة المرتبطة.","اختيار المتغير المطلوب تحديد نطاق له.","تحديد الحد الأدنى والحد الأقصى المسموح بهما للمتغير.","حفظ بيانات نطاق المتغير.","استخدام البند في إنشاء فاتورة وإدخال قيمة للمتغير داخل النطاق المحدد.","إعادة تجربة استخدام البند بإدخال قيمة للمتغير خارج النطاق المحدد."]'::jsonb, '["• يتم حفظ نطاق المتغير بنجاح","• يتم قبول قيمة المتغير عند إدخالها داخل النطاق المحدد","• لا يتم قبول قيمة المتغير خارج النطاق المحدد، ويتم عرض رسالة توضح عدم توافق الق"]'::jsonb, true),
  ('t173', 173, 'نظام الفواتير', 'سيناريوهات تعريف الفواتير', '', 16, 'إضافة مجموعة أكواد', 'التحقق من إمكانية إضافة مجموعة أكواد وتعريف الأكواد التابعة لها، بحيث يمكن استخدام هذه الأكواد في البيانات والعمليات المرتبطة بها داخل نظام الفواتير.', '["تسجيل الدخول إلى النظام.","الدخول إلى شاشة مجموعة الأكواد/ البيانات الاساسية .","إضافة مجموعة أكواد جديدة.","إدخال بيانات مجموعة الأكواد المطلوبة.","حفظ مجموعة الأكواد.","اختيار مجموعة الأكواد المضافة.","إضافة الأكواد التابعة للمجموعة.","إدخال بيانات كل كود وحفظه.","استخدام أحد الأكواد في العملية أو البند المرتبط بمجموعة الأكواد."]'::jsonb, '["• يتم إضافة مجموعة الأكواد بنجاح","• يتم حفظ الأكواد وربطها بمجموعة الأكواد المحددة","• تظهر الأكواد ضمن المجموعة الخاصة بها","• يمكن اختيار الأكواد من العمليات أو البنود المرتبطة"]'::jsonb, true),
  ('t174', 174, 'نظام الفواتير', 'سيناريوهات تعريف الفواتير', '', 17, 'إضافة بنود الفاتورة المرتبطة', 'التحقق من إمكانية ربط البنود بنوع الفاتورة، بحيث تكون البنود المرتبطة متاحة للاستخدام عند إنشاء أو إصدار فاتورة من نوع الفاتورة المحدد.', '["تسجيل الدخول إلى النظام.","الدخول إلى شاشة ينود الفاتورة المرتبطة /تعريف الفواتير.","اختيار نوع الفاتورة المطلوب.","الدخول إلى بنود الفاتورة المرتبطة.","اختيار البنود المطلوب ربطها بنوع الفاتورة.","حفظ البيانات."]'::jsonb, '["• يتم ربط البنود بنوع الفاتورة بنجاح","• تظهر البنود المرتبطة ضمن بيانات نوع الفاتورة","• تظهر البنود المرتبطة عند إنشاء فاتورة من نفس النوع","• لا تظهر البنود غير المرتبطة ضمن البنود المتاحة لهذا النوع من الفواتير","• يتم تطبيق إعدادات كل بند مرتبطة بنوع الفاتورة عند استخدامه في الفاتورة"]'::jsonb, true),
  ('t175', 175, 'نظام الفواتير', 'سيناريوهات تعريف الفواتير', '', 18, 'إضافة نوع الفاتورة إلى الدور', 'التحقق من إمكانية ربط نوع فاتورة محدد بالدور، بحيث يتمكن المستخدمون التابعون لهذا الدور من تنفيذ الإجراءات المسموح بها على نوع الفاتورة وفقًا لصلاحياتهم.', '["تسجيل الدخول إلى النظام بحساب لديه صلاحية إدارة الأدوار.","الدخول إلى شاشة انواع فواتير الادوار/الاعدادات.","اختيار الدور المطلوب.","إضافة نوع الفاتورة إلى الدور.","حفظ التعديلات.","تسجيل الدخول بمستخدم تابع للدور الذي تم تعديله.","الدخول إلى شاشة الفواتير.","محاولة التعامل مع نوع الفاتورة الذي تم ربطه بالدور."]'::jsonb, '["• يتم ربط نوع الفاتورة بالدور بنجاح","• يظهر نوع الفاتورة للمستخدمين التابعين للدور وفقًا للصلاحيات المحددة","• يستطيع المستخدم تنفيذ الإجراءات المسموح بها على نوع الفاتورة","• لا يستطيع المستخدم تنفيذ أي إجراء غير ممنوح له ضمن الدور"]'::jsonb, true),
  ('t176', 176, 'نظام الفواتير', 'سيناريوهات إصدار ومراجعة الفواتير', '', 1, 'إصدار الفاتورة بعد التحقق من الصلاحيات والتجهيز', 'التحقق من إمكانية إصدار الفاتورة فقط عند استيفاء متطلبات الإصدار، وذلك من خلال التحقق من امتلاك المستخدم صلاحية إصدار نوع الفاتورة، وإمكانية وصوله إلى الميناء المرتبط بنوع الفاتورة، ووجود تجهيز مكتمل للفاتورة.', '["تسجيل الدخول إلى النظام بالمستخدم المراد إصدار الفاتورة من خلاله.","الدخول إلى شاشة إصدار الفواتير.","التحقق من اختيار ميناء محدد .","اختيار نوع الفاتورة المراد إصدارها.","التحقق من امتلاك المستخدم الصلاحية على نوع الفاتورة المحدد.","التحقق من إمكانية وصول المستخدم إلى الميناء المرتبط بنوع الفاتورة.","التحقق من وجود تجهيز للفاتورة المطلوب إصدارها.","استكمال بيانات الفاتورة والتحقق من صحة البيانات.","اختيار استعراض الفاتورة .","اختيار أمر إصدار الفاتورة."]'::jsonb, '["• يتحقق النظام من صلاحية المستخدم على نوع الفاتورة قبل السماح بالإصدار","• يتحقق النظام من إمكانية وصول المستخدم إلى الميناء المرتبط بنوع الفاتورة","• يتحقق النظام من وجود تجهيز صالح للفاتورة قبل إصدارها","• في حالة استيفاء جميع الشروط، يتم إصدار الفاتورة بنجاح","• في حالة عدم امتلاك المستخدم صلاحية على نوع الفاتورة، لا يسمح النظام بإصدارها","• في حالة عدم إمكانية وصول المستخدم إلى الميناء المرتبط بنوع الفاتورة، لا يسمح النظام بإصدارها","• في حالة عدم وجود تجهيز للفاتورة، لا يسمح النظام بإصدارها"]'::jsonb, true),
  ('t177', 177, 'نظام الفواتير', 'سيناريوهات إصدار ومراجعة الفواتير', '', 2, 'مراجعة الفاتورة بعد الإصدار', 'التحقق من انتقال الفاتورة إلى حالة تحت المراجعة بعد إصدارها، وإمكانية اتخاذ الإجراء المناسب عليها وفقًا للصلاحيات المتاحة للمستخدم.', '["إصدار الفاتورة بعد استيفاء متطلبات الإصدار.","التحقق من انتقال حالة الفاتورة إلى تحت المراجعة.","الدخول إلى شاشة اصدار الفواتير.","اختيار الفاتورة المطلوب مراجعتها.","مراجعة بيانات الفاتورة والبنود والقيم المحسوبة.","اختيار الإجراء المناسب على الفاتورة:","اعتماد الفاتورة، الشغط على علامة ✓ .","رفض الفاتورة، اختيار الغاء الفاتورة ."]'::jsonb, '["• تنتقل الفاتورة بعد الإصدار إلى حالة تحت المراجعة","• تظهر الفاتورة في شاشة اصدار الفواتير","• يمكن للمستخدم اتخاذ إجراء رفض أو إلغاء الفاتورة إذا كان لديه الصلاحية المطلوبة","• عند اعتماد الفاتورة، يتم تحديث حالتها وفقًا لدورة العمل المعتمدة","• عند إلغاء الفاتورة، يتم تحديث حالتها إلى الحالة الخاصة بالإلغاء ولا يمكن التعامل معها كفاتورة صالحة"]'::jsonb, true),
  ('t178', 178, 'نظام الفواتير', 'سيناريوهات إصدار ومراجعة الفواتير', '', 3, 'إلغاء اعتماد الفاتورة بعد اعتمادها', 'التحقق من إمكانية إلغاء اعتماد الفاتورة بعد اعتمادها، وفقًا للصلاحيات وقواعد العمل المعتمدة، مع تحديث حالة الفاتورة بما يتوافق مع الإجراء المتخذ.', '["تسجيل الدخول إلى النظام بالمستخدم الذي لديه صلاحية إلغاء اعتماد الفاتورة.","الدخول إلى شاشة اصدار الفواتير.","اختيار الفاتورة التي حالتها معتمدة.","اختيار إجراء إلغاء الاعتماد.","تأكيد عملية إلغاء الاعتماد.","إعادة فتح بيانات الفاتورة والتحقق من حالتها."]'::jsonb, '["• يسمح النظام بإلغاء اعتماد الفاتورة للمستخدم الذي يمتلك الصلاحية المطلوبة","• يتم إلغاء اعتماد الفاتورة بنجاح","• تتغير حالة الفاتورة إلى الحالة تحت المراجعة المحددة في دورة العمل بعد إلغاء الاعتماد","• لا يتم التعامل مع الفاتورة كفاتورة معتمدة بعد إلغاء اعتمادها"]'::jsonb, true),
  ('t179', 179, 'نظام الفواتير', 'سيناريوهات إصدار ومراجعة الفواتير', '', 4, 'إعادة احتساب الفاتورة بعد الإلغاء', 'التحقق من إمكانية إعادة احتساب الفاتورة بعد إلغائها، بحيث يتم إعادة حساب قيم البنود والإجماليات وفقًا للبيانات والقواعد الحالية المعتمدة بالنظام.', '["تسجيل الدخول إلى النظام.","الدخول إلى شاشة اصدار الفواتير.","البحث عن فاتورة تم إلغاؤها.","اختيار الفاتورة.","تنفيذ إجراء إعادة الاحتساب بالضغط على اختيارات الفاتورة ثم اعادة الاحتساب .","التحقق من إعادة احتساب قيم بنود الفاتورة.","التحقق من إجمالي الفاتورة بعد إعادة الاحتساب.","حفظ أو تأكيد عملية إعادة الاحتساب وفقًا لدورة العمل المعتمدة."]'::jsonb, '["• يسمح النظام بإعادة احتساب الفاتورة الملغاة وفقًا لقواعد العمل","• يتم إعادة احتساب قيم البنود بناءً على البيانات والمتغيرات والقواعد المرتبطة بها","• يتم تحديث إجمالي الفاتورة وفقًا لنتائج إعادة الاحتساب","• لا يتم الاحتفاظ بالقيم السابقة إذا كانت قد تغيرت نتيجة إعادة الاحتساب","• يتم تسجيل عملية إعادة الاحتساب ضمن إجراءات الفاتورة"]'::jsonb, true),
  ('t180', 180, 'نظام الفواتير', 'سيناريوهات إصدار ومراجعة الفواتير', '', 5, 'إصدار فاتورة تموين السفن بالوقود', 'التحقق من إمكانية إصدار فاتورة الوقود واحتساب قيمتها وفقًا لنوع الوقود وكمية الوقود والفئة السعرية وطريقة حساب البنود وحالاتها المعرفة لنوع الفاتورة. المتطلبات: • وجود طلب تزود بالوقود. • يتم ارسال طلب الوقود الى المراجعة. • قبول طلب الوقود في المراجعة. • تنفيذ طلب التزود بالوقود. • اعتماد تنفيذ الطلب. • وجود نوع فاتورة الوقود والبند المرتبط به ضمن تعريفات الفواتير. • امتلاك المستخدم الصلاحية اللازمة لإصدار فاتورة الوقود. • إمكانية وصول المستخدم إلى الميناء المرتبط بنوع الفاتورة. • وجود تجهيز للفاتورة.', '["تسجيل الدخول إلى النظام.","الدخول إلى شاشة إصدار الفواتير.","التحقق من اختيار ميناء محدد لاصدار الفاتورة .","اختيار الجهة والادارة التابعة لفاتورة .","اختيار فاتورة الوقود.","اختيار السنة المالية.","اختيار الزيارة المرتبطة بطلب الوقود الذي تم قبوله وتنفيذه واعتماد تنفيذه.","التحقق من بيانات طلب التزود بالوقود.","التحقق من ظهور بيانات الوقود الفعلية التي تم تنفيذها.","التحقق من الفئة وكمية الوقود المستخدمة في حساب قيمة الفاتورة.","التحقق من احتساب قيمة بند الوقود وفقًا للمعادلة المعرفة الفئة × كمية الوقود.","مراجعة بيانات وقيمة الفاتورة.","إصدار الفاتورة."]'::jsonb, '["• يتم إنشاء فاتورة الوقود بناءً على طلب التزود بالوقود المقبول والمنفذ والمعتمد","• تظهر بيانات التنفيذ الفعلية في الفاتورة","• يتم احتساب قيمة بند الوقود وفقًا للفئة وكمية الوقود","• يتم احتساب إجمالي الفاتورة بشكل صحيح","• يتم إصدار الفاتورة بنجاح","• تنتقل الفاتورة إلى حالة تحت المراجعة بعد الإصدار"]'::jsonb, true),
  ('t181', 181, 'نظام الفواتير', 'سيناريوهات إصدار ومراجعة الفواتير', '', 6, 'إصدار فاتورة تموين السفن بالمياة', 'التحقق من إمكانية إصدار فاتورة المياة واحتساب قيمتها وفقًا لنوع الوقود وكمية المياة والفئة السعرية وطريقة حساب البنود وحالاتها المعرفة لنوع الفاتورة. المتطلبات: • وجود طلب تزود بالمياة . • يتم ارسال طلب المياة الى المراجعة. • قبول طلب المياة في المراجعة. • تنفيذ طلب التزود بالمياة. • اعتماد تنفيذ الطلب. • وجود نوع فاتورة المياة والبند المرتبط به ضمن تعريفات الفواتير. • امتلاك المستخدم الصلاحية اللازمة لإصدار فاتورة المياة. • إمكانية وصول المستخدم إلى الميناء المرتبط بنوع الفاتورة. • وجود تجهيز للفاتورة.', '["تسجيل الدخول إلى النظام.","الدخول إلى شاشة إصدار الفواتير.","التحقق من اختيار ميناء محدد لاصدار الفاتورة .","اختيار الجهة الادارة التابعة لفاتورة .","اختيار فاتورة تموين السفن.","اختيار السنة المالية.","اختيار الزيارة المرتبطة بطلب تموين السفن بالمياة الذي تم قبوله وتنفيذه واعتماد تنفيذه.","التحقق من بيانات طلب التزود بالمياة.","التحقق من ظهور بيانات التزود بالمياة الفعلية التي تم تنفيذها.","التحقق من الفئة وكمية المياة المستخدمة في حساب قيمة الفاتورة.","التحقق من احتساب قيمة بند الوقود وفقًا للمعادلة المعرفة الفئة × كمية المياة.","مراجعة بيانات وقيمة الفاتورة.","إصدار الفاتورة."]'::jsonb, '["• يتم إنشاء فاتورة المياة بناءً على طلب التزود بالمياة المقبول والمنفذ والمعتمد","• تظهر بيانات التنفيذ الفعلية في الفاتورة","• يتم احتساب قيمة بند المياة وفقًا للفئة وكمية المياة","• يتم احتساب إجمالي الفاتورة بشكل صحيح","• يتم إصدار الفاتورة بنجاح","• تنتقل الفاتورة إلى حالة تحت المراجعة بعد الإصدار"]'::jsonb, true),
  ('t182', 182, 'نظام الفواتير', 'سيناريوهات إصدار ومراجعة الفواتير', '', 7, 'إصدار فاتورة المخلفات', 'التحقق من إمكانية إصدار فاتورة رفع المخلفات واحتساب قيمتها وفقًا لنوع وكمية والفئة السعرية وطريقة حساب البنود وحالاتها المعرفة لنوع الفاتورة. المتطلبات: • الدخول الى نظام الرصد البيئي والحوادث. • الدخول الى شاشة طلبات جمع النفايات/ الطلبات. • تقدبم طلب جمع نفايات . • ارسال الطلب الى المراجعة . • قبول طلب جمع النفايات. • تنفيذ الطلب ثم اعتماده . • ارسال التجهيز الى الفوترة. • وجود نوع فاتورة المخلفات والبنود المرتبطة بها. • امتلاك المستخدم الصلاحية اللازمة لإصدار نوع الفاتورة. • إمكانية وصول المستخدم إلى الميناء المرتبط بنوع الفاتورة. • وجود تجهيز للفاتورة.', '["تسجيل الدخول إلى النظام.","الدخول إلى شاشة إصدار الفواتير.","التحقق من اختيار ميناء محدد لاصدار الفاتورة .","اختيار الجهة الادارة التابعة لفاتورة .","اختيار فاتورة رفع المخلفات.","اختيار السنة المالية.","اختيار الزيارة المرتبطة بطلب رفع المخلفات الذي تم قبوله وتنفيذه واعتماد تنفيذه.","التحقق من بيانات طلب رفم المخلفات.","التحقق من ظهور بيانات رفع المخلفات الفعلية التي تم تنفيذها.","التحقق من الفئة وكمية المخلفات المستخدمة في حساب قيمة الفاتورة.","مراجعة بيانات وقيمة الفاتورة.","إصدار الفاتورة"]'::jsonb, '["• يتم إصدار فاتورة المخلفات بنجاح بناءً على طلب إزالة المخلفات المقبول والمنفذ والمعتمد","• يتم احتساب قيم البنود والإجمالي وفقًا للقواعد المعرفة","• تنتقل الفاتورة إلى حالة تحت المراجعة بعد الإصدار"]'::jsonb, true),
  ('t183', 183, 'نظام الفواتير', 'سيناريوهات إصدار ومراجعة الفواتير', '', 8, 'إصدار فاتورة السفن (الفاتورة الشاملة)', 'التحقق من إمكانية إصدار فاتورة شاملة للسفينة بناءً على حركات زيارة السفينة والخدمات المقدمة لها، مع تجميع جميع البنود والخدمات المستحقة واحتساب قيمتها وفقًا للقواعد والإعدادات المالية المحددة لنوع الفاتورة. المتطلبات: • وجود طلب تراكي لزيارة السفينة. • ارسال طلب التراكي الى المراجعة . • قبول طلب التراكي من الجهات والادارات المخصصة لمراجعة طلبات التراكي . • اضافة وصول فعلي لزيارة السفينة. • اضافة حركات فعلية للسفينة من خارج الميناء الى الامتدادات والارصفة الموجودة داخل المنياء • تقديم طلب مغادرة لزيارة السفينة. • ارسال طب المغادرة الى المراجعة. • قبول طلب المغادرة من الجهات والادارات المخصصة لمراجعة طلبات المغادرة. • اضافة تصريح السفر والتحقق من صلاحياته وسريانه . • اضافة المغادرة الفعلية لزيارة السفينة • التحقق من مراجعة كشف الحركة واعتمادة • وجود البنود والخدمات المرتبطة بنوع الفاتورة الشاملة. • امتلاك المستخدم الصلاحية اللازمة لإصدار الفاتورة. • إمكانية وصول المستخدم إلى الميناء المرتبط بنوع الفاتورة. • وجود تجهيز للفاتورة.', '["تسجيل الدخول إلى النظام.","تسجيل الدخول إلى النظام.","الدخول إلى شاشة إصدار الفواتير.","التحقق من اختيار ميناء محدد لاصدار الفاتورة .","اختيار الجهة الادارة التابعة لفاتورة .","اختيار فاتورة السفن(الفاتورة الشاملة للسفينة)","اختيار السنة المالية.","اختيار الزيارة الذي تم اضافة المغادرة الفعليه لها واعتماد كشف الحركة.","التحقق من بيانات حركات السفينة.","التحقق من احتساب قيمة البنود.","مراجعة بيانات وقيمة الفاتورة.","إصدار الفاتورة."]'::jsonb, '["• يتم إنشاء الفاتورة الشاملة بناءً على حركات السفينة داخل الميناء","• تظهر جميع الخدمات والبنود المستحقة المرتبطة بالزيارة","• يتم احتساب قيمة كل بند وفقًا للقواعد المعرفة","• يتم احتساب إجمالي الفاتورة بشكل صحيح","• يتم إصدار الفاتورة بنجاح","• تنتقل الفاتورة إلى حالة تحت المراجعة بعد الإصدار"]'::jsonb, true),
  ('t184', 184, 'نظام الفواتير', 'سيناريوهات إصدار ومراجعة الفواتير', '', 9, 'إصدار فاتورة مزاولة نشاط لمتعامل', 'التحقق من إمكانية إصدار فاتورة مزاولة نشاط للمتعامل بناءً على طلب مزاولة النشاط المعتمد، واحتساب قيمة الفاتورة وفقًا للبنود والقواعد المالية المحددة لنوع الفاتورة. المتطلبات: • وجود طلب مزاولة نشاط للمتعامل. • أن يكون طلب مزاولة النشاط مقبولًا ومعتمدًا. • استيفاء الطلب لجميع البيانات والموافقات المطلوبة. • وجود نوع فاتورة مزاولة النشاط والبنود المرتبطة به ضمن تعريفات الفواتير. • امتلاك المستخدم الصلاحية اللازمة لإصدار نوع الفاتورة. • إمكانية وصول المستخدم إلى الميناء المرتبط بنوع الفاتورة. • وجود تجهيز للفاتورة.', '["تسجيل الدخول إلى النظام.","من علامة اسم المستخدم يتم تقديم طلب مزاولة نشاط للمتعامل.","استكمال بيانات الطلب والتأكيد على اختيار نوع الطلب تجديد/ اول مرة.","ارسال الطلب الى المراجعة.","من الشاشة الخاص بمراجعة طلبات مزاولة النشاط يتم قبول الطلب وتحديد تاريخ بداية ونهاية مزاولة النشاط للمتعامل .","الدخول إلى شاشة إصدار الفواتير.","اختيار فاتورة مزاولة نشاط متعامل.","اختيار طلب مزاولة النشاط الخاص بالمتعامل.","التحقق من بيانات المتعامل وبيانات طلب مزاولة النشاط.","التحقق من ظهور البنود المرتبطة بنوع الفاتورة.","التحقق من احتساب قيمة الفاتورة وفقًا للقواعد والإعدادات المعرفة.","مراجعة بيانات الفاتورة وقيمة البنود والإجمالي.","إصدار الفاتورة."]'::jsonb, '["• يتم إنشاء الفاتورة بناءً على طلب مزاولة النشاط المعتمد للمتعامل","• تظهر بيانات المتعامل وبيانات النشاط بشكل صحيح","• يتم احتساب قيمة البنود والإجمالي وفقًا للقواعد المعرفة","• يتم إصدار الفاتورة بنجاح","• تنتقل الفاتورة إلى حالة تحت المراجعة بعد الإصدار"]'::jsonb, true),
  ('t185', 185, 'نظام الفواتير', 'سيناريوهات إصدار ومراجعة الفواتير', '', 10, 'إصدار فاتورة الترانزيت', 'التحقق من إمكانية إصدار فاتورة الترانزيت بناءً على بيانات حاويات الترانزيت المربوطة بزيارة السفينة، واحتساب قيمة الخدمات والبنود المستحقة وفقًا للقواعد والإعدادات المالية المحددة لنوع الفاتورة. المتطلبات: • وجود عملية حاويات ترانزيت مستوفية للبيانات المطلوبة. • اكتمال الإجراءات والموافقات المطلوبة لعملية الترانزيت واعتماد اعداد الحاويات . • وجود نوع فاتورة الترانزيت والبنود المرتبطة به ضمن تعريفات الفواتير. • امتلاك المستخدم الصلاحية اللازمة لإصدار نوع فاتورة الترانزيت. • إمكانية وصول المستخدم إلى الميناء المرتبط بنوع الفاتورة. • وجود تجهيز للفاتورة.', '["تسجيل الدخول إلى النظام.","استقبال رسالة 803 لحاويات الترانزيت المحملة على سفينة او اضافة حاويات الترانزيت من شاشة قائمة الحاويات المحملة على سفينة في نظام البضائع العامة","اعتماد اعداد الحاويات.","الدخول إلى شاشة إصدار الفواتير.","التحقق من اختيار ميناء محدد لاصدار الفاتورة.","اختيار فاتورة الترانزيت.","اختيار زيارة السفينة المربوطة بحاويات الترانزيت المطلوب إصدار الفاتورة لها.","التحقق من بيانات عملية الترانزيت والبيانات المرتبطة بها.","التحقق من ظهور البنود والخدمات المرتبطة بنوع فاتورة الترانزيت.","التحقق من احتساب قيمة كل بند وفقًا لطريقة الحساب والمتغيرات المرتبطة به.","تطبيق الخصومات أو العقود أو سعر الصرف، إذا كانت منطبقة على الفاتورة.","مراجعة بيانات الفاتورة وقيم البنود وإجمالي الفاتورة.","إصدار الفاتورة."]'::jsonb, '["• يتم إنشاء فاتورة الترانزيت بناءً على عملية الترانزيت المحددة","• تظهر بيانات العملية والبنود والخدمات المستحقة بشكل صحيح","• يتم احتساب قيمة البنود والإجمالي وفقًا للقواعد المعرفة","• يتم تطبيق الخصومات والعقود وسعر الصرف عند انطباقها","• يتم إصدار الفاتورة بنجاح","• تنتقل الفاتورة إلى حالة تحت المراجعة بعد الإصدار"]'::jsonb, true),
  ('t186', 186, 'نظام الفواتير', 'سيناريوهات إصدار ومراجعة الفواتير', '', 11, 'إصدار فاتورة مقابل الترخيص بالانتفاع بأعمال الوكالة الملاحية', 'التحقق من إمكانية إصدار فاتورة مقابل الترخيص بالانتفاع بأعمال الوكالة الملاحية ، مع احتساب قيمة الفاتورة وفقًا للبنود والقواعد المالية المحددة لنوع الفاتورة. المتطلبات: • وجود منافيست مكود له بوالص تحتوي على سطور بضائع وحاويات عن طريق استقبال رسائل المنافيست . • ارسال المنافيست للمراجعة. • قبول المنافيست من المراجعة. • اعتماد بيان الشحنة وهو بيان موضح كل اعداد ووزن البضائع والحاويات الموجودة داخل المنافيست. • وجود نوع الفاتورة والبنود المرتبطة بها ضمن تعريفات الفواتير. • امتلاك المستخدم الصلاحية اللازمة لإصدار نوع الفاتورة. • إمكانية وصول المستخدم إلى الميناء المرتبط بنوع الفاتورة. • وجود تجهيز للفاتورة.', '["تسجيل الدخول إلى النظام.","الدخول الى شاشة المنافيست في نظام البضائع العامة.","التحقق من ارسال المنافيست الى المراجعة.","قبول المنافيست وتحويل حالة المنافيست الى مقبول وبالتالي تغيير حالة البوالص الى مقبولة.","اعتماد بيان الشحنة للمنافيست :-","المنافيست الوارد : يتم الدخول الى شاشة المنافيست الوارد/ ادارة البضائع العامة / المنافيست","المنافيست الصادر: يتم الدخول الى شاشة المنافيست الصادر/ ادارة البضائع العامة / المنافيست","منافيست طلب الارسال: يتم الدخول الى شاشة منافيست طلب الارسال/ ادارة البضائع العامة / الممافيست","الدخول إلى شاشة إصدار الفواتير.","التحقق من اختيار ميناء محدد لاصدار الفاتورة.","اختيار نوع الفاتورة مقابل الترخيص بالانتفاع بأعمال الوكالة الملاحية.","التحقق من ظهور البنود المرتبطة بنوع الفاتورة.","التحقق من احتساب قيمة البنود وفقًا للقواعد وطريقة الحساب المعرفة.","مراجعة بيانات الفاتورة وقيمة البنود وإجمالي الفاتورة.","إصدار الفاتورة."]'::jsonb, '["• يتم إنشاء فاتورة للترخيص بالانتفاع بأعمال الوكالة الملاحية","• تظهر البنود المرتبطة بنوع الفاتورة بشكل صحيح","• يتم احتساب قيمة الفاتورة وفقًا للقواعد المالية المحددة","• يتم إصدار الفاتورة بنجاح","• تنتقل الفاتورة إلى حالة تحت المراجعة بعد الإصدار"]'::jsonb, true),
  ('t187', 187, 'نظام الرصد البيئي والحوادث', 'سيناريوهات طلبات جمع النفايات', '', 1, 'إضافة أنواع النفايات (مسؤول البيئة)', 'يقوم مسؤول البيئة بالدخول إلى لوحة التحكم الخاصة بالبيانات الأساسية وتحديد قسم أنواع النفايات، ثم النقر على زر "إضافة" لإدخال تصنيف نفاية جديد.', '["تسجيل الدخول والانتقال إلى لوحة التحكم.","الضغط على قائمة \"البيانات الأساسية\" ثم اختيار \"أنواع النفايات\".","النقر على زر \"إضافة\" وإدخال اسم التصنيف الجديد.","النقر على زر \"حفظ\" ."]'::jsonb, '["• حفظ وتخزين نوع النفاية في قاعدة بيانات المنظومة"]'::jsonb, true),
  ('t188', 188, 'نظام الرصد البيئي والحوادث', 'سيناريوهات طلبات جمع النفايات', '', 2, 'إضافة طلب جمع النفايات وحفظه وإرساله (الوكيل الملاحي)', 'يقوم الوكيل الملاحي بإنشاء طلب جمع نفاية جديد وحفظه كمسودة، ومن ثم إرساله بشكل رسمي للجهات المختصة.', '["تسجيل الدخول والانتقال لخدمة طلبات جمع النفايات.","النقر على إضافة طلب جديد وتعبئة البيانات المطلوبة.","النقر على زر \"حفظ\" ليظهر الطلب كمسودة.","مراجعة الطلب والنقر على زر \"إرسال الطلب\" ."]'::jsonb, '["• حفظ الطلب وتحديث حالته إلى \"مرسل\" بنجاح"]'::jsonb, true),
  ('t189', 189, 'نظام الرصد البيئي والحوادث', 'سيناريوهات طلبات جمع النفايات', '', 3, 'مراجعة واعتماد طلب جمع النفايات', 'يقوم ممثل الجهات المختصة بمراجعة الطلبات الواردة لجمع النفايات والموافقة عليها.', '["الدخول إلى قائمة \"الطلبات الواردة\" وتصفية الطلبات بحالة \"مرسل\".","فتح تفاصيل الطلب لمراجعة البيانات والمرفقات.","النقر على زر \"قبول\" ."]'::jsonb, '["• تحديث حالة الطلب رسمياً إلى \"معتمد\""]'::jsonb, true),
  ('t190', 190, 'نظام الرصد البيئي والحوادث', 'سيناريوهات طلبات جمع النفايات', '', 4, 'رفض طلب جمع النفايات', 'يقوم ممثل الجهات المختصة بمراجعة الطلبات الواردة لجمع النفايات ورفضها عند عدم استيفاء الشروط والاشتراطات المطلوبة.', '["الدخول إلى قائمة \"الطلبات الواردة\" وتصفية الطلبات بحالة \"مرسل\".","فتح تفاصيل الطلب لمراجعة البيانات.","النقر على زر \"رفض\" ."]'::jsonb, '["• تحديث حالة الطلب رسمياً إلى \"مرفوض\""]'::jsonb, true),
  ('t191', 191, 'نظام الرصد البيئي والحوادث', 'سيناريوهات متابعة وتنفيذ عمليات رفع النفايات', '', 1, 'تسجيل ومتابعة توقيتات بداية ونهاية رفع النفايات', 'يقوم مسؤول مراقبة الأرصفة بالانتقال إلى شاشة "تسجيل بداية ونهاية جمع النفايات" وتعديل أوقات البدء والانتهاء وحالة الجمع وحفظ التغييرات.', '["الانتقال إلى قائمة \"عمليات المتابعة والرصد\" والضغط على شاشة تسجيل بداية ونهاية جمع النفايات .","تحديد متغيرات البحث ثم الضغط على زر \"بحث\" .","تحديد السطر المطلوب والنقر على زر \"التعديل\" واختيار حالة الجمع المناسبة.","إدخال تواريخ البداية والنهاية والنقر على زر \"حفظ\" ."]'::jsonb, '["• حفظ تفاصيل أوقات رفع النفايات بنجاح"]'::jsonb, true),
  ('t192', 192, 'نظام الرصد البيئي والحوادث', 'سيناريوهات متابعة وتنفيذ عمليات رفع النفايات', '', 2, 'متابعة تنفيذ عمليات رفع المخلفات وتحديث الكميات', 'مراجعة وتعديل بيانات الشاحنات والنفايات من شاشة متابعة التنفيذ، ثم إرسال الطلب لقسم الفوترة.', '["الانتقال إلى شاشة \"متابعة تنفيذ رفع المخلفات\" والبحث عن الطلب.","النقر على زر \"متابعة التنفيذ\" لعرض التفاصيل وتحديث كميات النفايات المرفوعة.","النقر على زر \"الحفظ\" ثم الضغط على زر \"إرسال الطلب للفوترة\" ."]'::jsonb, '["• تحديث حالة الطلب إلى \"مرسل للفوترة\""]'::jsonb, true),
  ('t193', 193, 'نظام الرصد البيئي والحوادث', 'سيناريوهات متابعة وتنفيذ عمليات رفع النفايات', '', 3, 'مراجعة واعتماد تنفيذ رفع النفايات وإصدار الفاتورة', 'استعراض ومراجعة تفاصيل التنفيذ للطلبات المرسلة للفوترة، ثم إصدار واعتماد الفاتورة المالية.', '["الانتقال إلى شاشة متابعة تنفيذ عمليات رفع النفايات واختيار \"إرسال للفوتره\" .","مراجعة الكميات الفعلية المسجلة والنقر على زر \"قبول\" ."]'::jsonb, '["• يتم اعتماد الطلب وإصدار الفاتورة المالية بنجاح"]'::jsonb, true),
  ('t194', 194, 'نظام الرصد البيئي والحوادث', 'سيناريوهات تسجيل وإصدار شهادة التخلص الآمن', '', 1, 'إضافة وتسجيل بيانات شهادة التخلص الآمن (مقدم الخدمة / الجهة المعنية)', 'إدخال وتوثيق بيانات شهادة التخلص الآمن بناءً على عمليات جمع ونقل النفايات المعتمدة، وتجهيزها للاعتماد.', '["الانتقال إلى قائمة \"شهادات التخلص الآمن\" والنقر على زر \"إضافة\" .","اختيار طلب جمع النفايات أو شحنة النفايات المرتبطة بعملية التخلص.","تعبئة البيانات الأساسية للشهادة (اسم الجهة المُتخلصَة، موقع/محطة التخلص النهائي، تواريخ وطرق التخلص).","إدخال الكميات الفعلية والتفاصيل الفنية لأنواع النفايات التي تم التخلص منها.","إرفاق المستندات الداعمة (مثل إيصالات الميزان أو التقارير الفنية).","النقر على زر \"حفظ\" لحفظ الشهادة كمسودة."]'::jsonb, '["• حفظ بيانات شهادة التخلص الآمن بنجاح وإظهارها في قائمة السجلات بالحالة \"مسودة\""]'::jsonb, true),
  ('t195', 195, 'نظام الرصد البيئي والحوادث', 'سيناريوهات تسجيل وإصدار شهادة التخلص الآمن', '', 2, 'إرسال شهادة التخلص الآمن لاعتمادها', 'مراجعة بيانات الشهادة المحفوظة كمسودة ومن ثم إرسالها بشكل رسمي إلى الجهات المختصة لمراجعتها واعتمادها.', '["فتح تفاصيل شهادة التخلص الآمن المحفوظة من قائمة المسودات.","التحقق من صحة كافة الحقول والكميات والمرفقات المدخلة.","النقر على زر \"إرسال للاعتماد\" ."]'::jsonb, '["• تحديث حالة الشهادة إلى \"مرسل للاعتماد\" وتوجيهها للجهات المعنية"]'::jsonb, true),
  ('t196', 196, 'نظام الرصد البيئي والحوادث', 'سيناريوهات تسجيل وإصدار شهادة التخلص الآمن', '', 3, 'مراجعة واعتماد شهادة التخلص الآمن (الجهات المختصة)', 'قيام ممثل الجهات المختصة بمراجعة شهادات التخلص الآمن المرسلة، والتحقق من مطابقتها للاشتراطات البيئية ثم اتخاذ القرار بالقبول أو الرفض.', '["الانتقال إلى قائمة \"شهادات التخلص الآمن\" وتصفية السجلات بحالة \"مرسل للاعتماد\".","فتح تفاصيل الشهادة ومراجعة المرفقات والبيانات المرتبطة بعملية التخلص.","النقر على زر \"قبول واعتماد\" (أو \"رفض\" مع تدوين سبب الرفض إن وجد)."]'::jsonb, '["• اعتماد الشهادة رسمياً وتحديث حالته إلى \"معتمد\" مع إتاحة خيار إصدارها وطباعتها"]'::jsonb, true),
  ('t197', 197, 'نظام الرصد البيئي والحوادث', 'سيناريوهات تسجيل وإصدار شهادة التخلص الآمن', '', 4, 'إصدار وطباعة شهادة التخلص الآمن', 'استعراض الشهادة المعتمدة بنجاح، وتوليد النسخة الرسمية النهائية منها وطباعتها أو تصديرها كملف PDF.', '["البحث عن شهادة التخلص الآمن ذات الحالة \"معتمد\" من شاشة الاستعلام.","النقر على زر \"عرض الشهادة\" أو \"طباعة\" .","مراجعة التنسيق النهائي للشهادة المتضمن الأختام وأرقام التوثيق الرسمية.","النقر على زر \"طباعة / تصدير PDF\" للحصول على النسخة الورقية أو الرقمية النهائية."]'::jsonb, '["• عرض الشهادة بتصميمها الرسمي الجاهز للطباعة والتوثيق القانوني بنجاح"]'::jsonb, true),
  ('t198', 198, 'نظام الرصد البيئي والحوادث', 'سيناريوهات إدارة ومتابعة أعمال المراقبة والرصد ومتابعة المحاضر', '', 1, 'تسجيل وإضافة بيانات المراقبة الأساسية (عناصر، أنواع أجهزة، أجهزة، ومحطات)', 'إدخال وتخزين عناصر المراقبة، أنواع الأجهزة، الأجهزة، ومحطات الرصد ضمن منظومة البيانات الأساسية والمتابعة.
